/**
 * 出图方案管理服务
 * 负责「NovelAI 正负提示词 + 模型配置」方案的增删改查与应用。
 *
 * - 方案存酒馆全局变量（跨角色卡共享）；
 * - API Key 不进方案：始终沿用全局运行时设置里的 novelAI.apiKey；
 * - 应用方案 = 把方案 config 写进 CGGenerationSettings.novelAI（保留密钥），
 *   下游 directorLLM.ts / novelAI.ts 无需改动。
 */

import { DEFAULT_CG_SETTINGS, IMAGE_PROFILE_STORAGE_KEY } from '../constants';
import type { ImageProfile, ImageProfileConfig, ImageProfileStorage, NovelAIConfig } from '../types';
import { loadCGSettings, saveCGSettings } from './cgTaskManager';
import { generateId } from './id';
import { notifyErrorThrottled } from './notify';

/** 当前方案结构版本 */
const PROFILE_SCHEMA_VERSION = 1;

/** 默认空存储 */
const DEFAULT_IMAGE_PROFILE_STORAGE: ImageProfileStorage = {
  profiles: [],
  activeProfileId: null,
};

/** 复制一份 NovelAI 配置并去掉 API Key */
function stripApiKey(config: NovelAIConfig): ImageProfileConfig {
  const copy = { ...config } as Partial<NovelAIConfig>;
  delete copy.apiKey;
  return copy as ImageProfileConfig;
}

/**
 * 校验并规范化导入的配置：与默认值合并（缺失字段回落默认，避免运行时报错），
 * 并剥离 apiKey（API Key 绝不进方案）。
 */
function sanitizeImportedConfig(raw: unknown): ImageProfileConfig {
  if (!raw || typeof raw !== 'object') {
    throw new Error('方案缺少有效的 config');
  }
  const partial = raw as Partial<NovelAIConfig>;
  const merged: NovelAIConfig = {
    ...DEFAULT_CG_SETTINGS.novelAI,
    ...partial,
    resolution: { ...DEFAULT_CG_SETTINGS.novelAI.resolution, ...partial.resolution },
  };
  return stripApiKey(merged);
}

// ====== 存取 ======

/** 从酒馆全局变量加载出图方案存储 */
export function loadImageProfileStorage(): ImageProfileStorage {
  try {
    const saved = getVariables({ type: 'global' }) as Record<string, any>;
    const storage = saved?.[IMAGE_PROFILE_STORAGE_KEY];
    if (storage && typeof storage === 'object' && Array.isArray(storage.profiles)) {
      return storage as ImageProfileStorage;
    }
  } catch (e) {
    console.warn('[imageProfileManager] 加载出图方案失败:', e);
  }
  return { ...DEFAULT_IMAGE_PROFILE_STORAGE };
}

/** 保存出图方案存储到酒馆全局变量（不含 API Key） */
export function saveImageProfileStorage(storage: ImageProfileStorage): void {
  try {
    const current = (getVariables({ type: 'global' }) as Record<string, any>) || {};
    current[IMAGE_PROFILE_STORAGE_KEY] = storage;
    replaceVariables(current, { type: 'global' });
  } catch (e) {
    console.error('[imageProfileManager] 保存出图方案失败:', e);
    notifyErrorThrottled('出图方案写入酒馆变量失败，刷新后可能丢失');
  }
}

// ====== 种子 / 应用 ======

/** 把方案 config 应用到运行时设置（保留全局 API Key） */
function applyConfigToSettings(config: ImageProfileConfig): void {
  const settings = loadCGSettings();
  saveCGSettings({
    ...settings,
    novelAI: {
      ...config,
      apiKey: settings.novelAI.apiKey,
    },
  });
}

/**
 * 首次使用时的内置默认方案：无任何方案时，用当前运行时 NovelAI 配置生成「默认」方案。
 * 不覆盖运行时设置，避免行为突变。
 */
export function ensureBuiltinImageProfile(): ImageProfileStorage {
  const storage = loadImageProfileStorage();
  if (storage.profiles.length > 0) return storage;
  const now = Date.now();
  const profile: ImageProfile = {
    id: generateId(),
    name: '默认',
    schemaVersion: PROFILE_SCHEMA_VERSION,
    builtin: true,
    createdAt: now,
    updatedAt: now,
    config: stripApiKey(loadCGSettings().novelAI),
  };
  storage.profiles = [profile];
  storage.activeProfileId = profile.id;
  saveImageProfileStorage(storage);
  return storage;
}

/**
 * 应用出图方案：把方案 config 写进运行时设置并设为当前启用方案。
 * 只有主动点「应用」或切换方案时才生效——旧楼层不会因此重绘。
 */
export function applyImageProfile(id: string): ImageProfileStorage {
  const storage = loadImageProfileStorage();
  const profile = storage.profiles.find(p => p.id === id);
  if (!profile) return storage;
  applyConfigToSettings(profile.config);
  storage.activeProfileId = id;
  saveImageProfileStorage(storage);
  return storage;
}

// ====== 方案管理 ======

/** 创建新方案；seedFromCurrent=true 时用当前运行时配置初始化 */
export function createImageProfile(name: string, seedFromCurrent = true): ImageProfileStorage {
  const storage = loadImageProfileStorage();
  const now = Date.now();
  const source = seedFromCurrent ? loadCGSettings().novelAI : DEFAULT_CG_SETTINGS.novelAI;
  const profile: ImageProfile = {
    id: generateId(),
    name,
    schemaVersion: PROFILE_SCHEMA_VERSION,
    createdAt: now,
    updatedAt: now,
    config: stripApiKey(source),
  };
  storage.profiles.push(profile);
  if (!storage.activeProfileId) storage.activeProfileId = profile.id;
  saveImageProfileStorage(storage);
  return storage;
}

/**
 * 从外部配置（如图片元数据）创建方案：分配新 id、名称冲突加后缀，
 * 字段与默认值合并并剥离 apiKey。
 */
export function createImageProfileFromConfig(
  name: string,
  config: Partial<NovelAIConfig>,
): ImageProfileStorage {
  const storage = loadImageProfileStorage();
  const now = Date.now();
  const baseName = name.trim() || '图片导入';
  const nameTaken = storage.profiles.some(p => p.name === baseName);
  storage.profiles.push({
    id: generateId(),
    name: nameTaken ? `${baseName} (导入)` : baseName,
    schemaVersion: PROFILE_SCHEMA_VERSION,
    builtin: false,
    createdAt: now,
    updatedAt: now,
    config: sanitizeImportedConfig(config),
  });
  saveImageProfileStorage(storage);
  return storage;
}

/** 复制方案（新 id、名称加「副本」） */
export function duplicateImageProfile(id: string): ImageProfileStorage {
  const storage = loadImageProfileStorage();
  const source = storage.profiles.find(p => p.id === id);
  if (!source) return storage;
  const now = Date.now();
  storage.profiles.push({
    ...source,
    id: generateId(),
    name: `${source.name} 副本`,
    builtin: false,
    createdAt: now,
    updatedAt: now,
    config: { ...source.config },
  });
  saveImageProfileStorage(storage);
  return storage;
}

/** 重命名方案 */
export function renameImageProfile(id: string, name: string): ImageProfileStorage {
  const storage = loadImageProfileStorage();
  const profile = storage.profiles.find(p => p.id === id);
  if (profile) {
    profile.name = name;
    profile.updatedAt = Date.now();
    saveImageProfileStorage(storage);
  }
  return storage;
}

/** 删除方案（内置方案不可删；删除当前启用方案后回落到首个并应用） */
export function deleteImageProfile(id: string): ImageProfileStorage {
  const storage = loadImageProfileStorage();
  const profile = storage.profiles.find(p => p.id === id);
  if (!profile || profile.builtin) return storage;
  const wasActive = storage.activeProfileId === id;
  storage.profiles = storage.profiles.filter(p => p.id !== id);
  if (wasActive) {
    const fallback = storage.profiles[0] ?? null;
    storage.activeProfileId = fallback?.id ?? null;
    // 同步运行时设置，避免「启用方案」与实际生效配置不一致
    if (fallback) applyConfigToSettings(fallback.config);
  }
  saveImageProfileStorage(storage);
  return storage;
}

/**
 * 更新方案；被更新的是当前启用方案时，同步应用到运行时设置（立即生效）。
 */
export function updateImageProfile(
  id: string,
  updater: (profile: ImageProfile) => ImageProfile,
): ImageProfileStorage {
  const storage = loadImageProfileStorage();
  const index = storage.profiles.findIndex(p => p.id === id);
  if (index < 0) return storage;
  const next = updater(storage.profiles[index]);
  storage.profiles[index] = { ...next, id, updatedAt: Date.now() };
  if (storage.activeProfileId === id) {
    applyConfigToSettings(storage.profiles[index].config);
  }
  saveImageProfileStorage(storage);
  return storage;
}

// ====== 导入 / 导出 ======

/** 导出单个方案为 JSON 字符串 */
export function exportImageProfile(id: string): string | null {
  const profile = loadImageProfileStorage().profiles.find(p => p.id === id);
  if (!profile) return null;
  return JSON.stringify(profile, null, 2);
}

/** 从 JSON 导入方案（分配新 id，名称冲突时加后缀） */
export function importImageProfile(json: string): ImageProfileStorage {
  let parsed: any;
  try {
    parsed = JSON.parse(json);
  } catch (e: any) {
    throw new Error(`方案 JSON 解析失败：${e.message}`);
  }
  if (!parsed || typeof parsed !== 'object' || typeof parsed.name !== 'string' || !parsed.config) {
    throw new Error('不是有效的出图方案文件');
  }
  const storage = loadImageProfileStorage();
  const now = Date.now();
  const baseName = parsed.name.trim() || '导入方案';
  const nameTaken = storage.profiles.some(p => p.name === baseName);
  storage.profiles.push({
    id: generateId(),
    name: nameTaken ? `${baseName} (导入)` : baseName,
    schemaVersion: PROFILE_SCHEMA_VERSION,
    builtin: false,
    createdAt: now,
    updatedAt: now,
    config: sanitizeImportedConfig(parsed.config),
  });
  saveImageProfileStorage(storage);
  return storage;
}
