/**
 * Voice Cache DB —— 语音缓存的服务器持久化层（双端共享）
 *
 * 合成的语音上传到酒馆服务器（user/images/novelui_voice），所有端共享；
 * 读取时从服务器取回 Blob（浏览器自带 HTTP 缓存负责速度），不再使用 IndexedDB。
 * 缓存键（模型 + 音色 + 文本）可能包含任意字符，用 FNV-1a 哈希成安全文件名。
 */

import {
  deleteMedia,
  forgetMedia,
  invalidateMediaList,
  listMediaNames,
  mediaRelativePath,
  MEDIA_TYPE,
  mimeToFormat,
  rememberMedia,
  serverUrl,
  uploadMedia,
} from './serverStore';

/** 语音在酒馆服务器上的子目录 */
const VOICE_FOLDER = 'novelui_voice';

/** 本会话内刚写入过的 key → 时间戳，避免覆盖后读到浏览器缓存的旧音频 */
const freshStamps = new Map<string, number>();

/** 是否已清理遗留的本地语音库 */
let legacyCleanupStarted = false;

/** 语音已迁到服务器，删掉遗留的 IndexedDB 库释放空间（一次性） */
function cleanupLegacyVoiceDb(): void {
  if (legacyCleanupStarted) return;
  legacyCleanupStarted = true;
  try {
    indexedDB.deleteDatabase('quiet_editor_voice_cache');
  } catch {
    /* 忽略 */
  }
}

/** 生成语音缓存键的短哈希（FNV-1a），作为服务器文件名 */
function fnv1aHex(input: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

/** 缓存键 → 服务器文件名（不含扩展名） */
function voiceFileName(key: string): string {
  return `v_${fnv1aHex(key)}`;
}

/** 将 Blob 转换为 data URL */
async function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

/** 去掉 data URL 前缀，取出纯 base64 */
function stripDataUrl(dataUrl: string): string {
  const index = dataUrl.indexOf(',');
  return index >= 0 ? dataUrl.slice(index + 1) : dataUrl;
}

// ====== 语音存取 ======

/**
 * 存入语音 Blob（上传到酒馆服务器）
 * @param key 缓存键（文本+音色）
 * @param audioBlob 音频 Blob
 */
export async function putVoiceAudio(key: string, audioBlob: Blob): Promise<void> {
  cleanupLegacyVoiceDb();
  const dataUrl = await blobToDataUrl(audioBlob);
  const format = mimeToFormat(audioBlob.type || 'audio/mpeg');
  await uploadMedia({
    base64: stripDataUrl(dataUrl),
    format,
    folder: VOICE_FOLDER,
    filename: voiceFileName(key),
  });
  rememberMedia(VOICE_FOLDER, MEDIA_TYPE.AUDIO, `${voiceFileName(key)}.${format}`);
  freshStamps.set(key, Date.now());
}

/**
 * 读取语音 Blob，服务器上不存在则返回 null
 * @param key 缓存键
 */
export async function getVoiceAudio(key: string): Promise<Blob | null> {
  cleanupLegacyVoiceDb();
  try {
    const names = await listMediaNames(VOICE_FOLDER, MEDIA_TYPE.AUDIO);
    const base = voiceFileName(key);
    const fileName = ['mp3', 'wav', 'ogg', 'flac', 'm4a', 'aac']
      .map(format => `${base}.${format}`)
      .find(candidate => names.has(candidate));
    if (!fileName) return null;

    const response = await fetch(
      `${serverUrl(mediaRelativePath(VOICE_FOLDER, fileName))}${freshStamps.has(key) ? `?t=${freshStamps.get(key)}` : ''}`,
    );
    if (!response.ok) return null;
    return await response.blob();
  } catch (error) {
    console.warn('[voiceCacheDB] 读取服务器语音失败:', error);
    return null;
  }
}

// ====== 清理操作 ======

/** 清空所有语音缓存（服务器目录） */
export async function clearAllVoiceCache(): Promise<void> {
  cleanupLegacyVoiceDb();
  const names = await listMediaNames(VOICE_FOLDER, MEDIA_TYPE.AUDIO, true);
  for (const name of names) {
    try {
      await deleteMedia(mediaRelativePath(VOICE_FOLDER, name));
      forgetMedia(VOICE_FOLDER, MEDIA_TYPE.AUDIO, name);
    } catch (e) {
      console.warn('[voiceCacheDB] 删除语音失败:', name, e);
    }
  }
  invalidateMediaList(VOICE_FOLDER, MEDIA_TYPE.AUDIO);
}

// ====== 缓存估算 ======

/** 获取缓存统计信息（服务器列表只提供文件名，故只统计条数） */
export async function getVoiceCacheStats(): Promise<{ count: number }> {
  cleanupLegacyVoiceDb();
  try {
    const names = await listMediaNames(VOICE_FOLDER, MEDIA_TYPE.AUDIO, true);
    return { count: names.size };
  } catch (error) {
    console.warn('[voiceCacheDB] 获取缓存统计失败:', error);
    return { count: 0 };
  }
}
