/**
 * 导演 LLM API 方案管理服务
 * 负责「导演 LLM 的 API 地址 + Key + 模型」方案的增删改查与应用。
 *
 * - 方案存酒馆全局变量（跨角色卡共享）；
 * - 应用方案 = 把方案的 endpoint / apiKey / model 写进 CGGenerationSettings.directorLLM，
 *   下游 directorLLM.ts 无需改动；
 * - NovelAI 只有单一会员账号，不纳入方案管理。
 */

import { DIRECTOR_API_PROFILE_STORAGE_KEY } from '../constants';
import type {
  DirectorApiProfile,
  DirectorApiProfileConfig,
  DirectorApiProfileStorage,
} from '../types';
import { loadCGSettings, saveCGSettings } from './cgTaskManager';
import { generateId } from './id';
import { notifyErrorThrottled } from './notify';

/** 当前方案结构版本 */
const PROFILE_SCHEMA_VERSION = 1;

/** 默认空存储 */
const DEFAULT_DIRECTOR_API_PROFILE_STORAGE: DirectorApiProfileStorage = {
  profiles: [],
  activeProfileId: null,
};

/**
 * 校验并规范化导入的配置：缺失字段回落空串，避免运行时报错。
 */
function sanitizeImportedConfig(raw: unknown): DirectorApiProfileConfig {
  if (!raw || typeof raw !== 'object') {
    throw new Error('方案缺少有效的 config');
  }
  const partial = raw as Partial<DirectorApiProfileConfig>;
  return {
    endpoint: typeof partial.endpoint === 'string' ? partial.endpoint : '',
    apiKey: typeof partial.apiKey === 'string' ? partial.apiKey : '',
    model: typeof partial.model === 'string' ? partial.model : '',
  };
}

// ====== 存取 ======

/** 从酒馆全局变量加载出导演 API 方案存储 */
export function loadDirectorApiProfileStorage(): DirectorApiProfileStorage {
  try {
    const saved = getVariables({ type: 'global' }) as Record<string, any>;
    const storage = saved?.[DIRECTOR_API_PROFILE_STORAGE_KEY];
    if (storage && typeof storage === 'object' && Array.isArray(storage.profiles)) {
      return storage as DirectorApiProfileStorage;
    }
  } catch (e) {
    console.warn('[directorApiProfileManager] 加载 API 方案失败:', e);
  }
  return { ...DEFAULT_DIRECTOR_API_PROFILE_STORAGE };
}

/** 保存导演 API 方案存储到酒馆全局变量 */
export function saveDirectorApiProfileStorage(storage: DirectorApiProfileStorage): void {
  try {
    const current = (getVariables({ type: 'global' }) as Record<string, any>) || {};
    current[DIRECTOR_API_PROFILE_STORAGE_KEY] = storage;
    replaceVariables(current, { type: 'global' });
  } catch (e) {
    console.error('[directorApiProfileManager] 保存 API 方案失败:', e);
    notifyErrorThrottled('API 方案写入酒馆变量失败，刷新后可能丢失');
  }
}

// ====== 应用 ======

/** 把方案配置应用到运行时设置（保留 min/max CG 数量等非连接字段） */
function applyConfigToSettings(config: DirectorApiProfileConfig): void {
  const settings = loadCGSettings();
  saveCGSettings({
    ...settings,
    directorLLM: {
      ...settings.directorLLM,
      endpoint: config.endpoint,
      apiKey: config.apiKey,
      model: config.model,
    },
  });
}

/**
 * 首次使用时的内置默认方案：无任何方案时，用当前运行时导演配置生成「默认」方案。
 * 不覆盖运行时设置，避免行为突变。
 */
export function ensureBuiltinDirectorApiProfile(): DirectorApiProfileStorage {
  const storage = loadDirectorApiProfileStorage();
  if (storage.profiles.length > 0) return storage;
  const now = Date.now();
  const profile: DirectorApiProfile = {
    id: generateId(),
    name: '默认',
    schemaVersion: PROFILE_SCHEMA_VERSION,
    builtin: true,
    createdAt: now,
    updatedAt: now,
    config: {
      endpoint: loadCGSettings().directorLLM.endpoint,
      apiKey: loadCGSettings().directorLLM.apiKey,
      model: loadCGSettings().directorLLM.model,
    },
  };
  storage.profiles = [profile];
  storage.activeProfileId = profile.id;
  saveDirectorApiProfileStorage(storage);
  return storage;
}

/**
 * 应用方案：写入运行时设置并设为当前启用方案。
 */
export function applyDirectorApiProfile(id: string): DirectorApiProfileStorage {
  const storage = loadDirectorApiProfileStorage();
  const profile = storage.profiles.find(p => p.id === id);
  if (!profile) return storage;
  applyConfigToSettings(profile.config);
  storage.activeProfileId = id;
  saveDirectorApiProfileStorage(storage);
  return storage;
}

// ====== 方案管理 ======

/** 创建新方案；seedFromCurrent=true 时用当前运行时配置初始化 */
export function createDirectorApiProfile(name: string, seedFromCurrent = true): DirectorApiProfileStorage {
  const storage = loadDirectorApiProfileStorage();
  const now = Date.now();
  const source: DirectorApiProfileConfig = seedFromCurrent
    ? {
        endpoint: loadCGSettings().directorLLM.endpoint,
        apiKey: loadCGSettings().directorLLM.apiKey,
        model: loadCGSettings().directorLLM.model,
      }
    : { endpoint: '', apiKey: '', model: '' };
  const profile: DirectorApiProfile = {
    id: generateId(),
    name,
    schemaVersion: PROFILE_SCHEMA_VERSION,
    createdAt: now,
    updatedAt: now,
    config: source,
  };
  storage.profiles.push(profile);
  if (!storage.activeProfileId) storage.activeProfileId = profile.id;
  saveDirectorApiProfileStorage(storage);
  return storage;
}

/** 复制方案（新 id、名称加「副本」） */
export function duplicateDirectorApiProfile(id: string): DirectorApiProfileStorage {
  const storage = loadDirectorApiProfileStorage();
  const source = storage.profiles.find(p => p.id === id);
  if (!source) return storage;
  const now = Date.now();
  storage.profiles.push({
    ...source,
    id: generateId(),
    name: `${source.name} 副本`,
    builtin: false,
    createdAt: now,
    updatedAt: now,
    config: { ...source.config },
  });
  saveDirectorApiProfileStorage(storage);
  return storage;
}

/** 重命名方案 */
export function renameDirectorApiProfile(id: string, name: string): DirectorApiProfileStorage {
  const storage = loadDirectorApiProfileStorage();
  const profile = storage.profiles.find(p => p.id === id);
  if (profile) {
    profile.name = name;
    profile.updatedAt = Date.now();
    saveDirectorApiProfileStorage(storage);
  }
  return storage;
}

/** 删除方案（内置方案不可删；删除当前启用方案后回落到首个并应用） */
export function deleteDirectorApiProfile(id: string): DirectorApiProfileStorage {
  const storage = loadDirectorApiProfileStorage();
  const profile = storage.profiles.find(p => p.id === id);
  if (!profile || profile.builtin) return storage;
  const wasActive = storage.activeProfileId === id;
  storage.profiles = storage.profiles.filter(p => p.id !== id);
  if (wasActive) {
    const fallback = storage.profiles[0] ?? null;
    storage.activeProfileId = fallback?.id ?? null;
    if (fallback) applyConfigToSettings(fallback.config);
  }
  saveDirectorApiProfileStorage(storage);
  return storage;
}

/**
 * 更新方案；被更新的是当前启用方案时，同步应用到运行时设置（立即生效）。
 */
export function updateDirectorApiProfile(
  id: string,
  updater: (profile: DirectorApiProfile) => DirectorApiProfile,
): DirectorApiProfileStorage {
  const storage = loadDirectorApiProfileStorage();
  const index = storage.profiles.findIndex(p => p.id === id);
  if (index < 0) return storage;
  const next = updater(storage.profiles[index]);
  storage.profiles[index] = { ...next, id, updatedAt: Date.now() };
  if (storage.activeProfileId === id) {
    applyConfigToSettings(storage.profiles[index].config);
  }
  saveDirectorApiProfileStorage(storage);
  return storage;
}

// ====== 导入 / 导出 ======

/** 导出单个方案为 JSON 字符串 */
export function exportDirectorApiProfile(id: string): string | null {
  const profile = loadDirectorApiProfileStorage().profiles.find(p => p.id === id);
  if (!profile) return null;
  return JSON.stringify(profile, null, 2);
}

/** 从 JSON 导入方案（分配新 id，名称冲突时加后缀） */
export function importDirectorApiProfile(json: string): DirectorApiProfileStorage {
  let parsed: any;
  try {
    parsed = JSON.parse(json);
  } catch (e: any) {
    throw new Error(`方案 JSON 解析失败：${e.message}`);
  }
  if (!parsed || typeof parsed !== 'object' || typeof parsed.name !== 'string' || !parsed.config) {
    throw new Error('不是有效的 API 方案文件');
  }
  const storage = loadDirectorApiProfileStorage();
  const now = Date.now();
  const baseName = parsed.name.trim() || '导入方案';
  const nameTaken = storage.profiles.some(p => p.name === baseName);
  storage.profiles.push({
    id: generateId(),
    name: nameTaken ? `${baseName} (导入)` : baseName,
    schemaVersion: PROFILE_SCHEMA_VERSION,
    builtin: false,
    createdAt: now,
    updatedAt: now,
    config: sanitizeImportedConfig(parsed.config),
  });
  saveDirectorApiProfileStorage(storage);
  return storage;
}
