interface GameInterfaceProps {
  settings: GameSettings;
  onToggleSetting: (setting: keyof GameSettings) => void;
  onShowLog: () => void;
  onShowSettings: () => void;
  onShowCGConfig: () => void;
  onShowVoiceConfig: () => void;
  onShowSaveLoad: () => void;
  onToggleFullscreen: () => void;
  isFullscreen: boolean;
  playSfx: () => void;
  onBgmChange: (url: string) => void;
  /** 从历史楼层继承的 BGM URL（由 App 层回溯得到，mount 时播放） */
  inheritedBgmUrl: string;
  /** 从历史楼层继承的背景信息（由 App 层回溯得到，作为 computeAccumulatedState 初始值） */
  inheritedBg: BgFullState | null;
  /** 已解析的对话段落 */
  segments: DialogueSegment[];
  /** 资源映射配置（从世界书异步加载） */
  resourceConfig: ResourceConfig;
  /** Roll 回调 */
  onRoll: () => void;
  isRolling: boolean;
  currentSwipeId: number;
  totalSwipes: number;
  onSwipeNav: (direction: 'prev' | 'next') => void;
  /** 确认选定当前 Roll 结果并写回酒馆楼层 */
  onCommitRoll: () => Promise<void>;
  /** 发送用户输入（带分支截断确认） */
  onSendUserInput: (text: string) => Promise<void>;
  /** 是否正在生成 AI 回复 */
  isGenerating: boolean;
  /** 小剧场数据（上一楼解析得到，生成期间播放） */
  skitLines: SkitLine[];
  /** Log 跳转目标段落索引（null 表示无跳转请求） */
  jumpToIndex: number | null;
  /** 跳转消费完成后的回调，用于清除跳转信号 */
  onJumpConsumed: () => void;
  /** 是否显示分支截断确认弹窗（由 App 层控制） */
  showBranchConfirm: boolean;
  /** 当前楼层 ID（用于 CG 生成和缓存） */
  messageId: number | null;
}

/**
 * 扫描 0..index 的所有段落，累积计算当前应有的效果状态
 */
function computeAccumulatedState(
  segments: DialogueSegment[],
  index: number,
  config: ResourceConfig,
  inheritedBg?: BgFullState | null,
): {
  bgUrl: string;
  bgName: string;
  bgThreat: ThreatLevel;
  bgTime: string;
  charName: string;
  /** 立绘显示的角色名（about 优先于 char） */
  spriteCharName: string;
  faceUrl: string;
  faceName: string;
  bgmUrl: string;
  bgmName: string;
  /** 是否处于 CG 模式 */
  isCgMode: boolean;
  /** CG 图 URL（仅 CG 模式有值） */
  cgUrl: string;
  cgName: string;
  /** 累积的段落级状态覆写（后出现的同 path 覆盖前面的） */
  accumulatedStats: StatOverride[];
} {
  // 使用继承的背景作为初始值（如果有的话）
  let bgName = inheritedBg?.场景 || '';
  let bgThreat: ThreatLevel = inheritedBg?.威胁等级 || '低';
  let bgTime = inheritedBg?.时间 || '';
  let bgKey = inheritedBg?.bgKey || '';
  let charName = '';
  let faceName = '';
  let bgmName = '';
  let aboutName = '';
  let cgName = '';
  let isCgMode = false;
  // 累积 [stat:] 覆写：
  //   set 模式：后者覆盖前者（状态类赋值）
  //   delta 模式：同 path 的增量累加（数值类增量）
  const statsMap = new Map<string, StatOverride>();

  for (let i = 0; i <= index; i++) {
    const eff = segments[i].effects;
    if (eff.bg) {
      bgName = eff.bg;
      if (eff.bgThreat) bgThreat = eff.bgThreat as ThreatLevel;
      if (eff.bgTime) bgTime = eff.bgTime;
      bgKey = eff.bgKey || '';
      // [bg:] 退出 CG 模式
      cgName = '';
      isCgMode = false;
    }
    if (eff.cg) {
      // [cg:] 进入 CG 模式
      cgName = eff.cg;
      isCgMode = true;
    }
    if (eff.char) {
      charName = eff.char;
      aboutName = ''; // char 切换时清除 about
      faceName = ''; // char 切换时清除 face
    }
    if (eff.about) {
      aboutName = eff.about;
      faceName = ''; // about 切换时清除 face，避免残留上一个角色的表情
    }
    if (eff.face) faceName = eff.face;
    if (eff.bgm) bgmName = eff.bgm;
    if (eff.stats) {
      for (const s of eff.stats) {
        if (s.mode === 'delta') {
          // 增量模式：累加到已有的 delta 上
          const existing = statsMap.get(s.path);
          if (
            existing &&
            existing.mode === 'delta' &&
            typeof existing.value === 'number' &&
            typeof s.value === 'number'
          ) {
            statsMap.set(s.path, { path: s.path, value: existing.value + s.value, mode: 'delta' });
          } else {
            statsMap.set(s.path, s);
          }
        } else {
          // 赋值模式：直接覆盖
          statsMap.set(s.path, s);
        }
      }
    }
  }

  // 立绘显示优先使用 about 指定的角色，其次使用 char（说话人）
  const spriteCharName = aboutName || charName;

  return {
    bgUrl: bgName ? resolveBackgroundImage(config, bgName, bgKey) : '',
    bgName,
    bgThreat,
    bgTime,
    charName,
    spriteCharName,
    faceUrl: spriteCharName ? resolveCharacterImage(config, spriteCharName, faceName) : '',
    faceName,
    bgmUrl: bgmName ? resolveBgmUrl(config, bgmName) : '',
    bgmName,
    isCgMode,
    cgUrl: isCgMode && cgName ? resolveCgImage(config, cgName) : '',
    cgName,
    accumulatedStats: [...statsMap.values()],
  };
}

/** 立绘层条目：entering 表示新挂载、用关键帧从透明淡入 */
type ActiveSprite = {
  id: string;
  url: string;
  charName: string;
  opacity: 'opacity-0' | 'opacity-100';
  entering?: boolean;
};

export const GameInterface: React.FC<GameInterfaceProps> = ({
  settings,
  onToggleSetting,
  onShowLog,
  onShowSettings,
  onShowCGConfig,
  onShowVoiceConfig,
  onShowSaveLoad,
  onToggleFullscreen,
  isFullscreen,
  playSfx,
  onBgmChange,
  inheritedBgmUrl,
  inheritedBg,
  segments,
  resourceConfig,
  onRoll,
  isRolling,
  currentSwipeId,
  totalSwipes,
  onSwipeNav,
  onCommitRoll,
  onSendUserInput,
  isGenerating,
  skitLines,
  jumpToIndex,
  onJumpConsumed,
  showBranchConfirm,
  messageId,
}) => {
  // 直接使用外部传入的段落
  const parsedSegments = segments;

  // 构造一个 fallback segment，防止空 segments 导致后续访问崩溃
  const FALLBACK_SEGMENT: DialogueSegment = {
    id: 'fallback',
    speaker: '系统',
    text: '',
    effects: {},
    isInnerMonologue: false,
    options: [],
  };

  // 范围 CG 状态（动态生成，保留双层交叠逻辑）


  // State for progression
  const [currentLineIndex, setCurrentLineIndex] = useState(0);
  // 打字机重置 key：每次需要强制重新触发打字机 effect 时递增
  const [typingResetKey, setTypingResetKey] = useState(0);
  // 安全 clamp：防止 segments 为空或 currentLineIndex 越界导致 undefined
  const safeIndex = parsedSegments.length > 0 ? Math.min(currentLineIndex, parsedSegments.length - 1) : 0;
  const currentSegment: DialogueSegment = parsedSegments[safeIndex] ?? FALLBACK_SEGMENT;

  // 当 segments 变化时（读档跳转、Roll 切换），重置到第一段
  const prevSegmentsRef = useRef(parsedSegments);
  useEffect(() => {
    if (prevSegmentsRef.current !== parsedSegments) {
      prevSegmentsRef.current = parsedSegments;
      setCurrentLineIndex(0);
      setShowingOptions(false);
      setDisplayedText('');
      setTypingResetKey(k => k + 1);
    }
  }, [parsedSegments]);

  // Log 跳转：当 jumpToIndex 变化时，跳转到目标段落并通知消费完成
  useEffect(() => {
    if (jumpToIndex !== null && jumpToIndex >= 0 && jumpToIndex < parsedSegments.length) {
      // 修复：将跳转视为前进导航，确保 BGM 等资源能正确同步
      isForwardRef.current = true;
      hasUserNavigatedRef.current = true;
      // 重置 BGM 追踪，允许跳转后的 BGM 更新
      prevBgmRef.current = '';

      setCurrentLineIndex(jumpToIndex);
      setShowingOptions(false);
      setDisplayedText('');
      setTypingResetKey(k => k + 1);
      onJumpConsumed();
    }
  }, [jumpToIndex]);

  // 选项页状态：独立页面，不与对话框共存
  const [showingOptions, setShowingOptions] = useState(false);

  // 语音操作按钮组状态
  const [showVoiceActions, setShowVoiceActions] = useState(false);
  const [isRegeneratingVoice, setIsRegeneratingVoice] = useState(false);
  const [isSavingVoice, setIsSavingVoice] = useState(false);

  // 是否已到达最后一段（停留在最后态）
  const isAtEnd = safeIndex >= parsedSegments.length - 1;
  // 当前段落是否有选项
  const hasOptions = (currentSegment.options?.length ?? 0) > 0;

  // 自行输入状态
  const [isCustomInput, setIsCustomInput] = useState(false);
  const [customText, setCustomText] = useState('');
  const [isSendingCustom, setIsSendingCustom] = useState(false);
  const customInputRef = useRef<HTMLInputElement>(null);

  // Track navigation direction: true = forward/initial, false = backward
  const isForwardRef = useRef(true);

  // ====== CG 动态生成状态 ======
  const [cgProgress, setCgProgress] = useState<CGTaskProgress>({ status: 'idle' });
  const [activeCGRange, setActiveCGRange] = useState<{
    startIndex: number;
    endIndex: number;
    imageUrl: string;
  } | null>(null);
  // CG 全屏查看器状态
  const [showCGViewer, setShowCGViewer] = useState(false);
  // 跟踪当前正在加载的范围，避免重复请求
  const loadingCGRangeRef = useRef<string | null>(null);

  // 监听 CG 生成进度
  useEffect(() => {
    const unsubscribe = onCGProgress(progress => {
      setCgProgress(progress);
    });
    return unsubscribe;
  }, []);

  // 当段落推进时，检查是否在 CG 范围内
  useEffect(() => {
    if (messageId === null || safeIndex < 0) return;

    let cancelled = false;
    const checkRange = async () => {
      const range = findCGRangeForParagraph(messageId, safeIndex);

      // 使用 ref 获取最新的 activeCGRange，避免将其加入依赖导致循环触发
      setActiveCGRange(prev => {
        if (range) {
          // 在范围内，检查是否需要加载新的 CG
          if (!prev || range.startIndex !== prev.startIndex || range.endIndex !== prev.endIndex) {
            // 生成范围标识符，用于去重
            const rangeKey = `${messageId}_${range.startIndex}_${range.endIndex}`;

            // 如果当前范围已经在加载中，不重复请求
            if (loadingCGRangeRef.current === rangeKey) {
              return prev;
            }

            // 标记为加载中
            loadingCGRangeRef.current = rangeKey;

            // 进入新范围，加载 CG
            // 关键：先 decode 再 setState，避免下一段 CG 在背景切换前就闪一下出现在屏上
            getCGForRange(messageId, range.startIndex, range.endIndex)
              .then(async imageUrl => {
                if (!imageUrl || cancelled) {
                  if (loadingCGRangeRef.current === rangeKey) {
                    loadingCGRangeRef.current = null;
                  }
                  return;
                }
                // 在 setState 之前先把图片解码完成，浏览器拿到 div 时可以直接绘制
                try {
                  const img = new Image();
                  img.src = imageUrl;
                  if (typeof img.decode === 'function') {
                    await img.decode();
                  } else {
                    await new Promise<void>(resolve => {
                      img.onload = () => resolve();
                      img.onerror = () => resolve();
                    });
                  }
                } catch {
                  // 解码失败不阻塞显示，仍然 setState
                }
                if (!cancelled) {
                  setActiveCGRange({
                    startIndex: range.startIndex,
                    endIndex: range.endIndex,
                    imageUrl,
                  });
                }
                if (loadingCGRangeRef.current === rangeKey) {
                  loadingCGRangeRef.current = null;
                }
              })
              .catch(() => {
                // 加载失败也要清除标记
                if (loadingCGRangeRef.current === rangeKey) {
                  loadingCGRangeRef.current = null;
                }
              });
            // 先保持之前的状态，等异步加载完成后再更新
            return prev;
          }
          // 如果已经在同一范围内，不做任何操作（保持显示当前 CG）
          return prev;
        } else if (prev) {
          // 离开范围，清除 CG 和加载标记
          loadingCGRangeRef.current = null;
          return null;
        }
        return prev;
      });
    };

    checkRange();
    return () => {
      cancelled = true;
    };
  }, [messageId, safeIndex, cgProgress.status]);

  // 前视预取：当 safeIndex 接近下一个 CG range 时，提前 fire-and-forget 触发生成
  // 用 ref 集合去重，避免重复请求；完成后由 range 检查 effect 重跑展示
  const lookaheadPrefetchRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    if (messageId === null || safeIndex < 0) return;

    const nextRange = findNextCGRangeAfter(messageId, safeIndex);
    if (!nextRange) return;

    const distance = nextRange.startIndex - safeIndex;
    if (distance <= 0 || distance > CG_LOOKAHEAD_DISTANCE) return;

    const rangeKey = `${messageId}_${nextRange.startIndex}_${nextRange.endIndex}`;
    if (lookaheadPrefetchRef.current.has(rangeKey)) return;
    lookaheadPrefetchRef.current.add(rangeKey);

    // fire-and-forget：预热下一张，失败则移除去重标记允许重试
    getCGForRange(messageId, nextRange.startIndex, nextRange.endIndex).catch(() => {
      lookaheadPrefetchRef.current.delete(rangeKey);
    });
  }, [messageId, safeIndex, cgProgress.status]);

  // 触发 CG 生成
  const handleTriggerCG = useCallback(async () => {
    if (!messageId) {
      return;
    }
    if (cgProgress.status === 'analyzing' || cgProgress.status === 'generating') {
      return;
    }
    playSfx();
    const paragraphs = buildDirectorParagraphs(parsedSegments);
    if (paragraphs.length === 0) {
      return;
    }

    // 使用范围生成
    const ranges = await triggerCGGenerationWithRange(paragraphs, messageId, resourceConfig.characterAppearances, true);

    if (ranges.length > 0) {
      // 检查当前段落是否在某个范围内，如果是则立即加载
      const currentRange = findCGRangeForParagraph(messageId, safeIndex);
      if (currentRange) {
        const imageUrl = await getCGForRange(messageId, currentRange.startIndex, currentRange.endIndex);
        if (imageUrl) {
          setActiveCGRange({
            startIndex: currentRange.startIndex,
            endIndex: currentRange.endIndex,
            imageUrl,
          });
        }
      }
    }
  }, [messageId, cgProgress.status, parsedSegments, resourceConfig.characterAppearances, playSfx, safeIndex]);

  // Accumulated state (computed from history scan)
  const accState = useMemo(
    () => computeAccumulatedState(parsedSegments, safeIndex, resourceConfig, inheritedBg),
    [parsedSegments, safeIndex, resourceConfig, inheritedBg],
  );

  // Scene toast state
  const [showSceneToast, setShowSceneToast] = useState(false);
  const sceneTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Character Sprite Management (cross-fade)
  // 新增 charName 字段用于判断是否同角色切换
  const [activeSprites, setActiveSprites] = useState<ActiveSprite[]>([]);
  // 追踪上一次的立绘角色名，用于判断是否同角色换表情还是换角色
  const prevSpriteCharRef = useRef('');
  // 追踪上一次的立绘URL，用于判断是否从无立绘状态切换到有立绘
  const prevSpriteUrlRef = useRef('');
  // 动态过渡时长：从无到有带缩放 700ms，立绘间切换 300ms
  const [spriteDuration, setSpriteDuration] = useState(700);

  // 立绘显示控制：跟踪背景/CG切换动画状态
  const [isBgTransitioning, setIsBgTransitioning] = useState(false);
  const bgTransitionTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const prevBgUrlRef = useRef('');
  const prevCgUrlRef = useRef('');
  const prevRangeCgUrlRef = useRef<string | null>(null);

  // Typing effect state
  const [displayedText, setDisplayedText] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  // Speed: 40ms base, 10ms for 3x (approx)
  const typingSpeed = settings.speed === 2 ? 10 : 40;
  const typingTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // 预解析缓存 ref：段落切换时一次性解析，打字机 tick 时直接使用
  const preparedTextRef = useRef<PreparedRichText | null>(null);
  // requestAnimationFrame ID ref
  const rafIdRef = useRef<number | null>(null);

  // Track previous bgm to avoid redundant changes
  const prevBgmRef = useRef('');
  // Track whether user has actively navigated (to skip initial render trigger)
  const hasUserNavigatedRef = useRef(false);
  // 语音配置 ref：让打字机 effect 读取最新值时不必把 resourceConfig.voices 列入依赖
  // 否则世界书加载、设置变更等场景下 voices 引用变化会导致打字机重启，
  // 表现为对话文本第 2-3 行时"消失一下再出现"。
  const voicesConfigRef = useRef(resourceConfig.voices);
  voicesConfigRef.current = resourceConfig.voices;

  // On mount: play inherited BGM from previous floors (resolved by App layer)
  // Only plays if there's a valid inherited URL — does NOT scan current floor's segments
  useEffect(() => {
    if (inheritedBgmUrl) {
      prevBgmRef.current = inheritedBgmUrl;
      onBgmChange(inheritedBgmUrl);
    }
  }, [inheritedBgmUrl]);

  // Cleanup timers on unmount
  useEffect(() => {
    return () => {
      if (sceneTimerRef.current) clearTimeout(sceneTimerRef.current);
      if (typingTimerRef.current) clearInterval(typingTimerRef.current);
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
    };
  }, []);

  // ========== State Synchronization ==========
  useEffect(() => {
    // 1. BGM change — only trigger when navigating forward (not on backward/prev)
    if (isForwardRef.current && accState.bgmUrl && accState.bgmUrl !== prevBgmRef.current) {
      prevBgmRef.current = accState.bgmUrl;
      onBgmChange(accState.bgmUrl);
    }

    // 2. Scene toast: show when bg changes on current segment (not in CG mode)
    // 只在前进时触发，后退时不触发（避免回顾剧情时重复弹出）
    if (isForwardRef.current && currentSegment.effects.bg && !accState.isCgMode) {
      setShowSceneToast(true);
      if (sceneTimerRef.current) clearTimeout(sceneTimerRef.current);
      sceneTimerRef.current = setTimeout(() => {
        setShowSceneToast(false);
      }, 2500);
    }

    // 4. 预加载后续段落的资源
    preloadNearbySegments(parsedSegments, safeIndex, resourceConfig);
  }, [currentLineIndex, parsedSegments]);

  // 3. 立绘切换：独立 effect，仅依赖 accState.faceUrl / spriteCharName
  // 拆分原因：原先与 BGM / stat 等回调混在同一 effect 内，
  // 父组件 setState 引发的 props 引用变化会让该 effect 重跑，
  // 导致 RAF 在切换到 opacity-100 之前被 cleanup 取消，
  // 表现为手机端立绘"消失-出现-消失-出现"两次稳定的闪烁。
  //
  // 修复：使用 useMemo 稳定目标值，避免父组件重渲染导致的不必要触发
  const spriteTarget = useMemo(
    () => ({ url: accState.faceUrl, charName: accState.spriteCharName }),
    [accState.faceUrl, accState.spriteCharName],
  );

  useEffect(() => {
    const targetFaceUrl = spriteTarget.url;
    const targetCharName = spriteTarget.charName;
    const prevUrl = prevSpriteUrlRef.current;
    const prevCharName = prevSpriteCharRef.current;

    // 去重：如果目标与当前一致，跳过
    if (targetFaceUrl === prevUrl) return;

    // 判断是否同角色切换表情（Via 优化：同角色瞬切，减少 GPU 负担）
    const isSameChar = !!(prevCharName && targetCharName && prevCharName === targetCharName);
    // 同角色换表情：0ms 瞬切（wasteland 策略）
    // 从无到有：700ms 渐变+缩放
    // 换角色：300ms 渐变
    const isFromEmpty = !prevUrl && !!targetFaceUrl;
    const duration = isSameChar ? 0 : isFromEmpty ? 700 : 300;
    setSpriteDuration(duration);
    prevSpriteCharRef.current = targetCharName;
    prevSpriteUrlRef.current = targetFaceUrl;

    let cancelled = false;
    let cleanupTimer: ReturnType<typeof setTimeout> | undefined;

    if (!targetFaceUrl) {
      // 无立绘目标，淡出所有
      setActiveSprites(prev => prev.map(s => ({ ...s, opacity: 'opacity-0' as const, entering: false })));
      cleanupTimer = setTimeout(() => {
        setActiveSprites([]);
      }, duration + 100);
    } else if (isSameChar) {
      // 同角色换表情：瞬切，不做动画
      setActiveSprites([
        {
          id: `${targetFaceUrl}-${Date.now()}`,
          url: targetFaceUrl,
          charName: targetCharName,
          opacity: 'opacity-100',
          entering: false,
        },
      ]);
    } else {
      // 换角色或从无到有：先预解码图片，再一次性切换（避免首帧闪现完整立绘）
      const img = new Image();
      img.src = targetFaceUrl;

      const updateWhenReady = async () => {
        try {
          if (typeof img.decode === 'function') {
            await img.decode();
          } else {
            await new Promise<void>((resolve, reject) => {
              img.onload = () => resolve();
              img.onerror = () => reject();
            });
          }
        } catch {
          // 解码失败也继续（降级：直接挂载，靠浏览器自身加载）
        }
        if (cancelled) return;

        // 一次性提交：旧立绘标记淡出（走 transition），新立绘标记 entering（走关键帧入场）。
        // 关键帧从 opacity:0 开始，因此挂载首帧就是透明的，不会再「先完整出现再淡入」。
        setActiveSprites(prev => {
          const next: ActiveSprite[] = prev.map(s => ({ ...s, opacity: 'opacity-0' as const, entering: false }));
          const existing = next.find(s => s.url === targetFaceUrl);
          if (existing) {
            // 已在 DOM 中（例如切回刚出现过的角色）：用过渡淡入即可
            existing.opacity = 'opacity-100';
            existing.entering = false;
          } else {
            next.push({
              id: `${targetFaceUrl}-${Date.now()}`,
              url: targetFaceUrl,
              charName: targetCharName,
              opacity: 'opacity-100',
              entering: true,
            });
          }
          return next;
        });

        // 清理不可见的立绘
        cleanupTimer = setTimeout(() => {
          if (!cancelled) {
            setActiveSprites(prev => prev.filter(s => s.opacity === 'opacity-100' || s.url === targetFaceUrl));
          }
        }, duration + 100);
      };

      updateWhenReady();
    }

    return () => {
      cancelled = true;
      if (cleanupTimer) clearTimeout(cleanupTimer);
    };
  }, [spriteTarget]);

  // ====== 背景/CG 已改用单层 DOM + key 策略，不再需要 prev/current 状态管理 ======

  // 范围 CG：简化为单一状态，使用key切换实现动画
  const [rangeCgUrl, setRangeCgUrl] = useState<string | null>(null);
  
  useEffect(() => {
    const targetRangeCgUrl = activeCGRange?.imageUrl ?? null;
    setRangeCgUrl(targetRangeCgUrl);
  }, [activeCGRange?.imageUrl]);

  // CG 画面焦点：按「图片宽高比 vs 容器宽高比」自适应，避免主体被底部对话框盖住。
  // 竖图在横屏容器里会被上下裁切，焦点上移优先保留脸/上半身；横图轻微上移/居中。
  const cgLayerRef = useRef<HTMLDivElement | null>(null);
  const [cgFocalY, setCgFocalY] = useState(50);
  const [cgContainerAspect, setCgContainerAspect] = useState(16 / 9);
  // 容器尺寸变化（旋转、切全屏：16:9 ↔ 超宽）时重算宽高比
  useEffect(() => {
    const layer = cgLayerRef.current;
    if (!layer) return;
    const syncAspect = () => {
      if (layer.clientHeight <= 0) return;
      const next = layer.clientWidth / layer.clientHeight;
      setCgContainerAspect(prev => (Math.abs(prev - next) > 0.01 ? next : prev));
    };
    syncAspect();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(syncAspect);
    observer.observe(layer);
    return () => observer.disconnect();
  }, []);
  useEffect(() => {
    const activeCg = rangeCgUrl ?? accState.cgUrl ?? null;
    if (!activeCg) {
      setCgFocalY(50);
      return;
    }
    let cancelled = false;
    const shortLandscape =
      typeof window !== 'undefined' &&
      window.matchMedia('(orientation: landscape) and (max-height: 550px)').matches;
    const image = new Image();
    image.onload = () => {
      if (cancelled) return;
      const imageAspect =
        image.naturalHeight > 0 ? image.naturalWidth / image.naturalHeight : cgContainerAspect;
      // 竖图：优先露出脸/上半身；略窄于容器的：轻微上移；与容器接近：居中
      let focal: number;
      if (imageAspect < 0.9) focal = 30;
      else if (imageAspect < cgContainerAspect - 0.05) focal = 42;
      else focal = 50;
      // 手机横屏对话框更高，再上移一点，让主体避开对话框
      if (shortLandscape) focal = Math.min(focal, 42);
      setCgFocalY(focal);
    };
    image.onerror = () => {
      if (!cancelled) setCgFocalY(50);
    };
    image.src = activeCg;
    return () => {
      cancelled = true;
    };
  }, [rangeCgUrl, accState.cgUrl, cgContainerAspect]);

  // 跟踪背景/CG切换状态：背景或CG变化时设置转场标志，动画结束后清除
  useEffect(() => {
    const currentBgUrl = accState.bgUrl;
    const currentCgUrl = accState.cgUrl;
    const currentRangeCgUrl = rangeCgUrl;
    
    const prevBg = prevBgUrlRef.current;
    const prevCg = prevCgUrlRef.current;
    const prevRangeCg = prevRangeCgUrlRef.current;
    
    // 首次渲染：初始化ref，不触发转场
    if (prevBg === '' && prevCg === '' && prevRangeCg === '') {
      prevBgUrlRef.current = currentBgUrl;
      prevCgUrlRef.current = currentCgUrl;
      prevRangeCgUrlRef.current = currentRangeCgUrl;
      return;
    }
    
    // 检测背景、CG或范围CG是否发生了变化
    const bgChanged = currentBgUrl !== prevBg;
    const cgChanged = currentCgUrl !== prevCg;
    const rangeCgChanged = currentRangeCgUrl !== prevRangeCg;
    
    if (bgChanged || cgChanged || rangeCgChanged) {
      // 背景/CG切换开始，隐藏立绘
      setIsBgTransitioning(true);
      
      // 清除之前的定时器
      if (bgTransitionTimerRef.current) {
        clearTimeout(bgTransitionTimerRef.current);
      }
      
      // 根据切换类型设置不同的等待时间
      // 普通背景：700ms，CG模式：700ms，范围CG：800ms
      const transitionDuration = rangeCgChanged ? 800 : 700;
      
      // 动画完成后允许立绘显示
      bgTransitionTimerRef.current = setTimeout(() => {
        setIsBgTransitioning(false);
      }, transitionDuration);
      
      // 更新ref
      prevBgUrlRef.current = currentBgUrl;
      prevCgUrlRef.current = currentCgUrl;
      prevRangeCgUrlRef.current = currentRangeCgUrl;
    }
    
    return () => {
      if (bgTransitionTimerRef.current) {
        clearTimeout(bgTransitionTimerRef.current);
      }
    };
  }, [accState.bgUrl, accState.cgUrl, rangeCgUrl]);

  // Auto-play effect — 有选项或已到末尾或正在显示选项时不自动前进
  useEffect(() => {
    let autoTimer: ReturnType<typeof setTimeout>;
    if (settings.autoPlay && !isTyping && !hasOptions && !isAtEnd && !showingOptions) {
      autoTimer = setTimeout(() => {
        handleNext();
      }, 2000);
    }
    return () => clearTimeout(autoTimer);
  }, [settings.autoPlay, isTyping, currentLineIndex, hasOptions, isAtEnd, showingOptions]);

  // Typing logic — 使用 requestAnimationFrame + 预解析缓存，避免每帧重新 tokenize
  // 同时触发语音播报（边打字边播放）
  useEffect(() => {
    // 双语支持：优先使用 textJa，如果没有则回退到 text
    const fullText = currentSegment.textJa || currentSegment.text;
    // TTS 文本：只使用日语部分
    const ttsText = currentSegment.textJa || currentSegment.text;

    setDisplayedText('');
    setIsTyping(true);

    if (!fullText) {
      setIsTyping(false);
      return;
    }

    // ====== 清空预加载队列，优先处理实时播放 ======
    cancelPreloadVoice();

    // ====== 语音播报：打字开始时立即触发合成和播放 ======
    // 通过 ref 读取最新 voices 配置，避免把 resourceConfig.voices 加入 effect 依赖
    const voiceConfig = voicesConfigRef.current;
    const speaker = currentSegment.speaker;

    if (voiceConfig?.enabled && voiceConfig.autoPlay && speaker !== '旁白' && voiceConfig.characterVoices[speaker]) {
      const voiceSettings = voiceConfig.characterVoices[speaker];
      // 异步调用，不阻塞打字机，使用 ttsText（仅日语）
      // allowGenerate=false：自动播放只播已生成的语音，不自动生成。
      // 生成只来自「语音预加载」或手动点姓名后的「生成」，避免边读边偷偷生成。
      synthesizeAndPlayVoice(ttsText, voiceSettings, voiceConfig, settings.volumeVoice, false).catch(err => {
        console.error(`[GameInterface] 角色 ${speaker} 语音播放失败:`, err);
      });
    }
    // ====== 语音播报结束 ======

    // 一次性预解析，后续 tick 只做 slice
    const prepared = prepareRichText(fullText);
    preparedTextRef.current = prepared;
    const totalVisible = prepared.totalVisible;
    let visibleIndex = 0;
    let lastTime = performance.now();

    // 立即显示第一个字符
    visibleIndex++;
    setDisplayedText(slicePreparedRichText(prepared, visibleIndex));

    if (visibleIndex >= totalVisible) {
      setIsTyping(false);
      return;
    }

    const frame = (now: number) => {
      const elapsed = now - lastTime;
      if (elapsed >= typingSpeed) {
        // 根据实际经过时间计算应推进的字符数（补偿掉帧）
        const steps = Math.max(1, Math.floor(elapsed / typingSpeed));
        visibleIndex = Math.min(visibleIndex + steps, totalVisible);
        lastTime = now - (elapsed % typingSpeed);
        setDisplayedText(slicePreparedRichText(prepared, visibleIndex));

        if (visibleIndex >= totalVisible) {
          setIsTyping(false);
          rafIdRef.current = null;
          return;
        }
      }
      rafIdRef.current = requestAnimationFrame(frame);
    };

    rafIdRef.current = requestAnimationFrame(frame);

    return () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
    };
  }, [
    currentLineIndex,
    settings.speed,
    currentSegment.text,
    currentSegment.textJa,
    currentSegment.textZh,
    typingResetKey,
    // 注意：刻意不依赖 resourceConfig.voices —— 通过 voicesConfigRef 读取最新值，
    // 避免世界书加载完成或父组件重渲导致 voices 引用变化时打字机被强制重启，
    // 表现为多行对话刚打到第 2-3 行时整段消失再重打。
  ]);

  const handleNext = () => {
    if (showingOptions) return; // 选项页显示时不允许前进
    // 已到达最后一段且无选项，完全停留，不做任何操作
    if (isAtEnd && !hasOptions) return;
    // 如果当前段有选项且打字已完成，进入选项页
    if (hasOptions && !isTyping) {
      setShowingOptions(true);
      setIsCustomInput(false);
      setCustomText('');
      return;
    }
    isForwardRef.current = true;
    hasUserNavigatedRef.current = true;
    setDisplayedText('');
    if (currentLineIndex < parsedSegments.length - 1) {
      setCurrentLineIndex(prev => prev + 1);
    }
  };

  const handlePrev = () => {
    // 如果在选项页，先退回到对话
    if (showingOptions) {
      setShowingOptions(false);
      setIsCustomInput(false);
      setCustomText('');
      playSfx();
      return;
    }
    if (currentLineIndex <= 0) return;
    isForwardRef.current = false;
    playSfx();
    setDisplayedText('');
    setCurrentLineIndex(prev => prev - 1);
  };

  // 发送用户输入：委托给 App 层处理（含分支截断确认）
  const sendUserInput = useCallback(
    async (text: string) => {
      await onSendUserInput(text);
    },
    [onSendUserInput],
  );

  // 选项点击：将选项文本作为用户输入发送给酒馆
  const handleOptionClick = useCallback(
    async (option: DialogueOption) => {
      playSfx();
      try {
        await sendUserInput(option.text);
      } catch (e) {
        console.error('[visual-novel-ui] 发送选项失败:', e);
      }
    },
    [playSfx, sendUserInput],
  );

  // 自行输入发送
  const handleCustomInputSend = useCallback(async () => {
    const text = customText.trim();
    if (!text || isSendingCustom) return;
    playSfx();
    setIsSendingCustom(true);
    try {
      await sendUserInput(text);
    } catch (e) {
      console.error('[visual-novel-ui] 发送自定义输入失败:', e);
    } finally {
      setIsSendingCustom(false);
      setCustomText('');
      setIsCustomInput(false);
    }
  }, [customText, isSendingCustom, playSfx, sendUserInput]);

  const handleTextBoxClick = () => {
    if (isTyping) {
      // 跳过打字机：取消 raf，直接显示完整文本，同时停止语音
      stopCurrentVoice(); // 停止当前播放的语音
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
      if (typingTimerRef.current) clearInterval(typingTimerRef.current);
      const prepared = preparedTextRef.current;
      // 双语支持：优先使用 textJa，回退到 text
      const fullText = currentSegment.textJa || currentSegment.text;
      setDisplayedText(prepared ? prepared.fullHtml : renderRichText(fullText));
      setIsTyping(false);
    } else {
      handleNext();
    }
  };

  // ====== 语音操作功能 ======

  // 检查当前角色是否有语音配置
  const hasVoiceConfig = useCallback(() => {
    const voiceConfig = resourceConfig.voices;
    const speaker = currentSegment.speaker;
    return voiceConfig?.enabled && speaker !== '旁白' && !!voiceConfig.characterVoices[speaker];
  }, [resourceConfig.voices, currentSegment.speaker]);

  // 手动播放当前语音
  const handlePlayVoice = useCallback(async () => {
    const voiceConfig = resourceConfig.voices;
    const speaker = currentSegment.speaker;
    if (!voiceConfig?.enabled || !voiceConfig.characterVoices[speaker]) return;

    const ttsText = currentSegment.textJa || currentSegment.text;
    const voiceSettings = voiceConfig.characterVoices[speaker];

    playSfx();
    try {
      await manualPlayVoice(ttsText, voiceSettings, voiceConfig, settings.volumeVoice);
    } catch (err) {
      console.error('[GameInterface] 手动播放语音失败:', err);
    }
  }, [resourceConfig.voices, currentSegment, settings.volumeVoice, playSfx]);

  // 重新生成语音
  const handleRegenerateVoice = useCallback(async () => {
    const voiceConfig = resourceConfig.voices;
    const speaker = currentSegment.speaker;
    if (!voiceConfig?.enabled || !voiceConfig.characterVoices[speaker]) return;

    const ttsText = currentSegment.textJa || currentSegment.text;
    const voiceSettings = voiceConfig.characterVoices[speaker];

    playSfx();
    setIsRegeneratingVoice(true);
    try {
      await regenerateVoice(ttsText, voiceSettings, voiceConfig);
    } catch (err) {
      console.error('[GameInterface] 重新生成语音失败:', err);
      notifyError('重新生成失败，请检查网络或 API 配置');
    } finally {
      setIsRegeneratingVoice(false);
    }
  }, [resourceConfig.voices, currentSegment, playSfx]);

  // 保存当前语音
  const handleSaveVoice = useCallback(async () => {
    const voiceConfig = resourceConfig.voices;
    const speaker = currentSegment.speaker;
    if (!voiceConfig?.enabled || !voiceConfig.characterVoices[speaker]) return;

    const ttsText = currentSegment.textJa || currentSegment.text;
    const voiceSettings = voiceConfig.characterVoices[speaker];

    playSfx();
    setIsSavingVoice(true);
    try {
      await saveTempVoice(ttsText, voiceSettings.voice, voiceConfig.model);
      setShowVoiceActions(false); // 保存后关闭按钮组
    } catch (err) {
      console.error('[GameInterface] 保存语音失败:', err);
    } finally {
      setIsSavingVoice(false);
    }
  }, [resourceConfig.voices, currentSegment, playSfx]);

  // 取消语音操作
  const handleCancelVoice = useCallback(async () => {
    const voiceConfig = resourceConfig.voices;
    const speaker = currentSegment.speaker;
    if (!voiceConfig?.enabled || !voiceConfig.characterVoices[speaker]) return;

    const ttsText = currentSegment.textJa || currentSegment.text;
    const voiceSettings = voiceConfig.characterVoices[speaker];

    playSfx();
    try {
      await cancelTempVoice(ttsText, voiceSettings.voice, voiceConfig.model);
      setShowVoiceActions(false);
    } catch (err) {
      console.error('[GameInterface] 取消语音失败:', err);
    }
  }, [resourceConfig.voices, currentSegment, playSfx]);

  // 段落切换时关闭语音操作按钮组
  useEffect(() => {
    setShowVoiceActions(false);
  }, [currentLineIndex]);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl+F11 全屏快捷键
      if (e.ctrlKey && e.key === 'F11') {
        e.preventDefault();
        onToggleFullscreen();
        return;
      }

      if (e.ctrlKey || e.altKey || e.metaKey) return;

      switch (e.key) {
        case 'ArrowRight':
        case 'ArrowDown':
        case ' ':
        case 'Enter':
          e.preventDefault();
          handleTextBoxClick();
          break;
        case 'ArrowLeft':
        case 'ArrowUp':
          e.preventDefault();
          handlePrev();
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleTextBoxClick, handlePrev, onToggleFullscreen]);

  return (
    <div className="font-editor-sans relative flex h-full w-full flex-col overflow-hidden bg-[var(--color-cozy-bg)] text-[var(--color-cozy-ink)] transition-colors duration-1000">
      {/* ====== 优化后的背景/CG 层 - 简化DOM结构，提升移动端性能 ====== */}
      <div ref={cgLayerRef} className="absolute inset-0 z-0 overflow-hidden" style={{ willChange: 'contents' }}>
        {/* Fallback 米白色垫底（无背景时显示） - 合并为单层 */}
        <div
          className="absolute inset-0 z-0 transition-opacity duration-500"
          style={{
            opacity: !accState.bgUrl && !accState.cgUrl && !rangeCgUrl ? 1 : 0,
            background:
              'linear-gradient(180deg,#f8f3ee 0%,#efe5da 55%,#e6d9cd 100%), radial-gradient(circle at top right, rgba(221,184,176,0.28), transparent 32%), radial-gradient(circle at bottom left, rgba(188,199,186,0.24), transparent 30%)',
            transform: 'translateZ(0)',
            willChange: 'opacity',
          }}
        />

        {/* 普通背景（非 CG 模式） */}
        {!accState.isCgMode && accState.bgUrl && (
          <div
            key={accState.bgUrl}
            className="absolute inset-0 bg-cover bg-center bg-no-repeat z-0 animate-in fade-in"
            style={{
              backgroundImage: `url(${accState.bgUrl})`,
              transform: 'scale(1.02) translateZ(0)',
              willChange: 'opacity',
              animationDuration: '700ms',
            }}
          />
        )}

        {/* CG 模式背景 */}
        {accState.isCgMode && accState.cgUrl && (
          <div
            key={accState.cgUrl}
            className="absolute inset-0 bg-cover bg-no-repeat z-[5] animate-in fade-in"
            style={{
              backgroundImage: `url(${accState.cgUrl})`,
              backgroundPosition: `center ${cgFocalY}%`,
              transition: 'background-position 400ms ease',
              transform: 'scale(1.02) translateZ(0)',
              willChange: 'opacity',
              animationDuration: '700ms',
            }}
          />
        )}

        {/* 深色垫底层（仅 CG 模式显示） */}
        <div
          className="absolute inset-0 bg-gradient-to-b from-stone-900/95 to-stone-950/98 z-[4] transition-opacity duration-300"
          style={{
            opacity: accState.isCgMode || rangeCgUrl ? 1 : 0,
            pointerEvents: 'none',
            transform: 'translateZ(0)',
            willChange: 'opacity',
          }}
        />

        {/* 范围 CG 层（z-[6]） - 简化为单层，使用key切换 */}
        {rangeCgUrl && (
          <div
            key={rangeCgUrl}
            className="absolute inset-0 bg-cover bg-no-repeat z-[6] animate-in fade-in cursor-pointer"
            style={{
              backgroundImage: `url(${rangeCgUrl})`,
              backgroundPosition: `center ${cgFocalY}%`,
              imageRendering: '-webkit-optimize-contrast' as any,
              transform: 'translateZ(0)',
              willChange: 'opacity',
              animationDuration: '800ms',
            }}
            onClick={() => setShowCGViewer(true)}
            title="点击全屏查看 CG"
          />
        )}

        {/* Vignette 装饰 - 仅有图片时显示 */}
        <div
          className="absolute inset-0 z-[7] pointer-events-none transition-opacity duration-500"
          style={{
            opacity: accState.bgUrl || accState.cgUrl || rangeCgUrl ? 1 : 0,
            transform: 'translateZ(0)',
            willChange: 'opacity',
            backgroundImage:
              'radial-gradient(circle at top right, rgba(255,255,255,0.16), transparent 28%), radial-gradient(circle at bottom left, rgba(188,199,186,0.08), transparent 28%)',
          }}
        />
      </div>

      {/* Top Right Control Bar */}
      <TopControlBar
        settings={settings}
        onToggleSetting={onToggleSetting}
        onShowLog={onShowLog}
        onShowSettings={onShowSettings}
        onShowCGConfig={onShowCGConfig}
        onShowVoiceConfig={onShowVoiceConfig}
        onShowSaveLoad={onShowSaveLoad}
        onToggleFullscreen={onToggleFullscreen}
        isFullscreen={isFullscreen}
        playSfx={playSfx}
        onBack={handlePrev}
        onRoll={onRoll}
        isRolling={isRolling}
        currentSwipeId={currentSwipeId}
        totalSwipes={totalSwipes}
        onSwipeNav={onSwipeNav}
        onCommitRoll={onCommitRoll}
        onTriggerCG={handleTriggerCG}
        cgProgress={cgProgress}
      />

      {/* Scene Record Indicator - 采用 M3 卡片与优雅留白设计 */}
      <div
        className={`game-scene-toast absolute top-6 left-6 sm:left-10 z-30 pointer-events-none select-none transition-all duration-[600ms] ease-[cubic-bezier(0.2,0,0,1)] ${showSceneToast && accState.bgName && !accState.isCgMode ? 'opacity-100 translate-y-0 blur-none' : 'opacity-0 -translate-y-4 blur-[6px]'}`}
      >
        {accState.bgName && (
          <div className="relative min-w-[280px] sm:min-w-[340px] max-w-[440px] rounded-[32px] sm:rounded-[36px] bg-[rgba(255,255,255,0.95)] px-7 py-5 sm:px-8 sm:py-6 text-[#1e242b] shadow-[0_18px_48px_rgba(30,36,43,0.12),inset_0_1px_2px_rgba(255,255,255,1)] border border-[rgba(255,255,255,0.95)]">
            {/* 顶栏：标签 + 状态点 */}
            <div className="flex items-center justify-between mb-2.5">
              <span className="font-mono-retro text-[10px] sm:text-[11px] uppercase tracking-[0.16em] text-[#84919e] font-semibold">
                SCENE · LOCATION
              </span>
              <span
                className={`h-3 w-3 rounded-full shrink-0 ${THREAT_TOAST_STYLES[accState.bgThreat]?.dot || 'bg-[#526070]'} ${THREAT_TOAST_STYLES[accState.bgThreat]?.glow || ''}`}
              />
            </div>

            {/* 场景名大标题 */}
            <h1 className="font-sans-m3 text-[22px] sm:text-[26px] font-bold text-[#1e242b] tracking-[0.02em] leading-tight mb-3.5">
              {accState.bgName}
            </h1>

            {/* 底部信息标签胶囊 */}
            <div className="flex flex-wrap items-center gap-2.5">
              {accState.bgTime && (
                <span className="font-sans-m3 text-[11px] sm:text-[12px] tracking-wide font-medium bg-[#edf1f4] px-3.5 py-1 rounded-full text-[#526070]">
                  {accState.bgTime}
                </span>
              )}
              {accState.bgThreat && (
                <span
                  className={`font-sans-m3 text-[11px] sm:text-[12px] tracking-wide font-medium px-3.5 py-1 rounded-full bg-[#edf1f4] ${THREAT_TOAST_STYLES[accState.bgThreat]?.color || 'text-[#526070]'}`}
                >
                  威胁度 · {accState.bgThreat}
                </span>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Stat Toast Overlay — 技能/物品变化通知 */}
      <StatToastOverlay
        accumulatedStats={accState.accumulatedStats}
        isForward={isForwardRef.current}
      />

      {/* Character Sprite Layer — CG 模式或有范围 CG 时隐藏立绘，背景转场期间也隐藏 */}
      <div
        className={`absolute inset-0 z-10 pointer-events-none flex items-end justify-center overflow-visible transition-opacity duration-500 ${accState.isCgMode || rangeCgUrl || isBgTransitioning ? 'opacity-0' : 'opacity-100'}`}
        style={{ willChange: 'opacity' }}
      >
        {activeSprites.map(sprite => {
          // entering = 新挂载的立绘：用关键帧从透明淡入（挂载首帧即 0，不闪）
          const animating = !!sprite.entering && spriteDuration > 0;
          const animation =
            animating && spriteDuration === 700
              ? `nvl-sprite-in ${spriteDuration}ms ease-in-out both`
              : animating
                ? `nvl-sprite-in-soft ${spriteDuration}ms ease-in-out both`
                : undefined;

          return (
            <div
              key={sprite.id}
              className={`absolute bottom-0 left-1/2 -translate-x-1/2 h-full ease-in-out origin-bottom ${sprite.opacity}`}
              style={{
                ...(animation ? { animation } : {}),
                ...(!animation && spriteDuration > 0 ? { transition: `opacity ${spriteDuration}ms ease-in-out` } : {}),
                transform: 'translate3d(0,0,0)',
                willChange: animating ? 'opacity, transform' : 'opacity',
              }}
            >
              <img
                src={sprite.url}
                alt="Character"
                className="h-full w-auto min-h-full object-cover object-bottom"
                style={{
                  imageRendering: 'high-quality' as React.CSSProperties['imageRendering'],
                  display: 'block',
                  backfaceVisibility: 'hidden',
                  WebkitBackfaceVisibility: 'hidden',
                }}
              />
            </div>
          );
        })}
      </div>

      {/* ========== 选项独立页（电影感轻透分支） ========== */}
      {showingOptions && !isGenerating && !showBranchConfirm && (
        <div className="absolute inset-0 z-[25] flex items-center justify-center bg-[rgba(18,14,12,0.72)] backdrop-blur-md transition-all duration-500">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(221,184,176,0.12),transparent_65%)] pointer-events-none" />

          <div
            className="relative flex h-full w-full flex-col items-center justify-center p-4 sm:p-6"
            onClick={() => {
              setIsCustomInput(false);
              setCustomText('');
              handlePrev();
            }}
          >
            {/* 彻底去除死板的外层大实色底板，改为通透无框的分支列表 */}
            <div
              className="relative z-10 flex w-full max-w-xl flex-col items-center gap-3.5 sm:gap-4 md:gap-5"
              onClick={e => e.stopPropagation()}
            >
              {/* 顶部极其典雅的分支指示徽章 */}
              <div className="mb-2 flex items-center gap-3 select-none opacity-80">
                <span className="h-px w-8 bg-gradient-to-r from-transparent to-[rgba(255,255,255,0.4)]" />
                <span className="font-mono-retro text-[9px] md:text-[10px] tracking-[0.3em] text-[#d6c9be] uppercase">
                  BRANCH SELECTION
                </span>
                <span className="h-px w-8 bg-gradient-to-l from-transparent to-[rgba(255,255,255,0.4)]" />
              </div>

              {/* 选项列表：彻底告别任何胶囊、框、圆角，纯粹的诗行对白与抉择心流 */}
              <div className="w-full flex flex-col divide-y divide-[rgba(255,255,255,0.08)]">
                {(currentSegment.options ?? []).map((option, idx) => (
                  <button
                    key={option.id}
                    onClick={() => handleOptionClick(option)}
                    className="group relative flex w-full items-baseline justify-between py-4 sm:py-5 px-3 sm:px-4 text-left transition-all duration-300 ease-out cursor-pointer active:scale-[0.995]"
                    style={{
                      animationDelay: `${idx * 80}ms`,
                      animation: 'optionSlideIn 0.5s cubic-bezier(0.16,1,0.3,1) forwards',
                      opacity: 0,
                      transform: 'translateY(12px)',
                    }}
                  >
                    {/* 选项主体：左侧声部微标 + 典雅诗行文本 */}
                    <div className="flex items-baseline gap-3.5 sm:gap-4 flex-1">
                      {/* 分支编号或极淡光标 */}
                      <span className="font-mono-retro text-[10px] md:text-xs tracking-[0.2em] text-[#a89d95] group-hover:text-[var(--color-cozy-accent)] transition-colors select-none">
                        0{idx + 1}.
                      </span>

                      {/* 选项文字正文 */}
                      <span className="font-serif-sc text-[15.5px] sm:text-[17px] md:text-[18px] leading-relaxed tracking-[0.06em] text-[#e8dfd8] group-hover:text-white transition-colors duration-300 drop-shadow-[0_2px_8px_rgba(0,0,0,0.8)]">
                        {option.text}
                      </span>
                    </div>

                    {/* 右侧悬浮引导小星光（平时隐匿，悬停浮现） */}
                    <span className="font-serif-sc text-xs text-[var(--color-cozy-accent)] opacity-0 -translate-x-2 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-300 select-none ml-3 shrink-0">
                      ✦
                    </span>
                  </button>
                ))}

                {/* 自行输入入口：与选项同构的典雅诗行 */}
                {!isCustomInput ? (
                  <button
                    onClick={() => {
                      playSfx();
                      setIsCustomInput(true);
                      setTimeout(() => customInputRef.current?.focus(), 50);
                    }}
                    className="group relative flex w-full items-baseline justify-between py-4 sm:py-5 px-3 sm:px-4 text-left transition-all duration-300 ease-out cursor-pointer opacity-70 hover:opacity-100"
                    style={{
                      animationDelay: `${(currentSegment.options?.length ?? 0) * 80}ms`,
                      animation: 'optionSlideIn 0.5s cubic-bezier(0.16,1,0.3,1) forwards',
                      opacity: 0,
                      transform: 'translateY(12px)',
                    }}
                  >
                    <div className="flex items-baseline gap-3.5 sm:gap-4 flex-1">
                      <span className="font-mono-retro text-[10px] md:text-xs tracking-[0.2em] text-[#8a7f77] group-hover:text-[var(--color-cozy-accent)] transition-colors select-none">
                        ✦.
                      </span>
                      <span className="flex items-center gap-2 font-serif-sc text-sm sm:text-base tracking-[0.1em] text-[#b8ada5] group-hover:text-[#f5ede4] italic transition-colors">
                        <PenLine size={13} className="opacity-60 group-hover:opacity-100 transition-opacity" />
                        自行书写心绪…
                      </span>
                    </div>
                  </button>
                ) : (
                  /* 自行输入激活状态：无框下划线输入行 */
                  <div
                    className="relative flex w-full items-center justify-between py-3.5 px-3 sm:px-4 gap-3 border-b-2 border-[var(--color-cozy-accent)] transition-all duration-300"
                    style={{
                      animation: 'optionSlideIn 0.3s cubic-bezier(0.16,1,0.3,1) forwards',
                      opacity: 0,
                      transform: 'translateY(6px)',
                    }}
                  >
                    <input
                      ref={customInputRef}
                      type="text"
                      value={customText}
                      onChange={e => setCustomText(e.target.value)}
                      onKeyDown={e => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          e.stopPropagation();
                          handleCustomInputSend();
                        }
                        if (e.key === 'Escape') {
                          e.preventDefault();
                          e.stopPropagation();
                          setIsCustomInput(false);
                          setCustomText('');
                        }
                      }}
                      placeholder="写下你的想法……（按 Enter 发送）"
                      disabled={isSendingCustom}
                      className="flex-1 bg-transparent font-serif-sc text-[15px] sm:text-[17px] text-white outline-none placeholder:text-[#8a7f77] placeholder:text-sm disabled:opacity-50"
                    />

                    <button
                      onClick={e => {
                        e.stopPropagation();
                        handleCustomInputSend();
                      }}
                      disabled={isSendingCustom || !customText.trim()}
                      className="font-mono-retro text-xs tracking-[0.2em] text-[var(--color-cozy-accent)] hover:text-white transition-colors duration-200 cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed shrink-0"
                    >
                      SEND ↵
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ========== 生成等待遮罩 ========== */}
      {isGenerating && (
        <div className="absolute inset-0 z-[25] bg-[rgba(20,16,14,0.82)] backdrop-blur-md flex flex-col items-center justify-start pt-[14dvh] sm:pt-[16dvh] px-5 sm:px-8 overflow-y-auto transition-all duration-700">
          {skitLines.length > 0 ? (
            /* 有小剧场：电影感暗幕对白，纯净呈现无框思绪流 */
            <div className="w-full max-w-xl flex flex-col items-center">
              <SkitPlayer lines={skitLines} />
            </div>
          ) : (
            /* 无小剧场：暗幕极简居中等待 */
            <div className="my-auto flex flex-col items-center gap-3.5 px-7 py-5 rounded-2xl bg-[rgba(32,26,24,0.7)] border border-[rgba(255,255,255,0.08)] shadow-[0_16px_40px_rgba(0,0,0,0.4)] backdrop-blur-xl">
              <div className="h-2 w-2 rounded-full bg-[var(--color-cozy-accent)] animate-ping" />
              <div className="font-serif-sc text-sm md:text-base tracking-[0.24em] text-[#e8dfd8] animate-pulse">
                正在继续书写…
              </div>
            </div>
          )}
        </div>
      )}

      {/* ========== 对话区域：借鉴图4/图8音乐播放器与消息流的高级呼吸感排版 ========== */}
      {!showingOptions && !isGenerating && (
        <div
          className="absolute inset-x-0 bottom-0 z-20 w-full pointer-events-none flex flex-col justify-end"
          style={{ paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) + 2vh)' }}
        >
          {/* 超透柔和渐变托底 */}
          <div
            className="absolute inset-x-0 bottom-0 h-[35%] pointer-events-none"
            style={{
              background:
                'linear-gradient(to top, rgba(235,240,245,0.45) 0%, rgba(235,240,245,0.12) 50%, transparent 100%)',
            }}
          />

          {/* 悬浮容器 */}
          <div className="relative pointer-events-auto w-full px-5 sm:px-10 md:px-[10%] lg:px-[14%] max-w-[1180px] mx-auto">
            {/* 真正拥有留白美学与材质感的 M3 Expressive 对话卡片（参考图4大圆角播放器卡片） */}
            <div
              onClick={handleTextBoxClick}
              className={`group/card relative z-10 w-full rounded-[22px] sm:rounded-[26px] bg-[rgba(255,255,255,0.97)] text-[#2c343f] border border-[rgba(255,255,255,0.95)] shadow-[0_12px_32px_rgba(30,36,43,0.1),inset_0_1px_2px_rgba(255,255,255,1)] cursor-pointer transition-all duration-300 ease-[cubic-bezier(0.2,0,0,1)] px-8 py-1.5 sm:px-11 sm:py-1.5 md:px-14 md:py-2 flex flex-col justify-between ${
                currentSegment.speaker !== '旁白'
                  ? 'h-[114px] sm:h-[118px] md:h-[122px]'
                  : 'h-[92px] sm:h-[96px] md:h-[100px]'
              }`}
              style={{
                transform: 'translateZ(0)',
                backfaceVisibility: 'hidden',
                WebkitBackfaceVisibility: 'hidden',
                willChange: 'contents',
              }}
            >
              {/* 顶部元信息行：说话人优雅排版 + 纯粹语音微胶囊（旁白时不渲染该节点） */}
              {currentSegment.speaker !== '旁白' && (
                <div className="flex items-center justify-between mt-1 sm:mt-1.5 mb-0.5 sm:mb-1 select-none shrink-0 animate-in fade-in duration-300">
                  <div className="flex items-center gap-3">
                    {/* 说话人名：参考图4/图8，优雅纯净的 Typography */}
                    <span
                      onClick={e => {
                        if (hasVoiceConfig()) {
                          e.stopPropagation();
                          playSfx();
                          setShowVoiceActions(!showVoiceActions);
                        }
                      }}
                      className={`font-sans-m3 text-[15px] sm:text-[16px] md:text-[17px] font-bold tracking-[0.02em] text-[#2c343f] ${hasVoiceConfig() ? 'cursor-pointer hover:text-[#526070] transition-colors' : ''}`}
                    >
                      {currentSegment.speaker}
                    </span>

                    {/* 展开的语音控制（优雅药丸） */}
                    {hasVoiceConfig() && showVoiceActions && (
                      <div
                        className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#edf1f4] border border-[#dde3e8] animate-in fade-in duration-200"
                        onClick={e => e.stopPropagation()}
                      >
                        <button
                          onClick={handlePlayVoice}
                          className="p-1 rounded-full text-[#526070] hover:text-[#1e242b] hover:bg-white transition-all cursor-pointer"
                          title="播放语音"
                        >
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor">
                            <path d="M8 5v14l11-7z" />
                          </svg>
                        </button>
                        <button
                          onClick={handleRegenerateVoice}
                          disabled={isRegeneratingVoice}
                          className="p-1 rounded-full text-[#526070] hover:text-[#1e242b] hover:bg-white transition-all disabled:opacity-30 cursor-pointer"
                          title="重新生成"
                        >
                          {isRegeneratingVoice ? (
                            <svg className="animate-spin" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                              <path d="M21 12a9 9 0 11-6.219-8.56" />
                            </svg>
                          ) : (
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                              <path d="M1 4v6h6M23 20v-6h-6" />
                              <path d="M20.49 9A9 9 0 005.64 5.64L1 10m22 4l-4.64 4.36A9 9 0 013.51 15" />
                            </svg>
                          )}
                        </button>
                        <button
                          onClick={handleSaveVoice}
                          disabled={isSavingVoice}
                          className="p-1 rounded-full text-[#526070] hover:text-[#7ca58a] hover:bg-white transition-all disabled:opacity-30 cursor-pointer"
                          title="保存"
                        >
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                            <path d="M19 21H5a2 2 0 01-2-2V5a2 2 0 012-2h11l5 5v11a2 2 0 01-2 2z" />
                            <polyline points="17 21 17 13 7 13 7 21" />
                            <polyline points="7 3 7 8 15 8" />
                          </svg>
                        </button>
                        <button
                          onClick={handleCancelVoice}
                          className="p-1 text-[#84919e] hover:text-[#c4384c] hover:bg-white rounded-full transition-colors cursor-pointer"
                          title="关闭"
                        >
                          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                            <line x1="18" y1="6" x2="6" y2="18" />
                            <line x1="6" y1="6" x2="18" y2="18" />
                          </svg>
                        </button>
                      </div>
                    )}
                  </div>

                  {/* 参考图4：轻盈的流向虚线/点阵微装饰 */}
                  <div className="flex items-center gap-1.5 opacity-40 group-hover/card:opacity-75 transition-opacity">
                    <span className="h-1.5 w-1.5 rounded-full bg-[#84919e]" />
                    <span className="h-1.5 w-1.5 rounded-full bg-[#84919e]" />
                    <span className="h-1.5 w-1.5 rounded-full bg-[#526070]" />
                  </div>
                </div>
              )}

              {/* 对白正文：上边距随「有无姓名」自由补偿，正文位置保持稳定 */}
              <div
                className={`game-dialogue-text relative z-10 font-sans-m3 w-full flex-1 min-h-[4.5em] overflow-y-auto text-[15px] leading-[1.5] tracking-[0.01em] scrollbar-none ${currentSegment.speaker === '旁白' ? 'mt-2 sm:mt-3' : ''} ${currentSegment.isInnerMonologue ? 'text-[#6b7684] italic' : 'text-[#384250]'}`}
              >
                {/* 双语对白 */}
                {currentSegment.textJa && currentSegment.textZh ? (
                  <span>
                    <span dangerouslySetInnerHTML={{ __html: displayedText }} />
                    {isTyping && (
                      <span className="ml-2 inline-block h-[0.7em] w-[0.7em] rounded-full animate-pulse align-baseline bg-[#526070]" />
                    )}
                    {!isTyping && (
                      <span className="ml-3 text-[0.8em] leading-relaxed text-[#747f8d]">
                        {currentSegment.textZh}
                      </span>
                    )}
                  </span>
                ) : (
                  <>
                    <span dangerouslySetInnerHTML={{ __html: displayedText }} />
                    {isTyping && (
                      <span className="ml-2 inline-block h-[0.7em] w-[0.7em] rounded-full animate-pulse align-baseline bg-[#526070]" />
                    )}
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* CG 生成进度指示器 */}
      <CGProgressBar progress={cgProgress} />

      {/* CG 全屏查看器 */}
      {showCGViewer && activeCGRange && (
        <CGViewer
          imageBase64={activeCGRange.imageUrl}
          onClose={() => setShowCGViewer(false)}
          fileName={`cg_${messageId ?? 'unknown'}_${activeCGRange.startIndex}-${activeCGRange.endIndex}`}
          prompt={(() => {
            if (!messageId) return undefined;
            // 从范围配方中获取 prompt
            const range = findCGRangeForParagraph(messageId, safeIndex);
            return range?.prompt ?? undefined;
          })()}
          characters={(() => {
            if (!messageId) return undefined;
            // 从范围配方中获取 characters
            const range = findCGRangeForParagraph(messageId, safeIndex);
            return range?.characters ?? undefined;
          })()}
          seed={(() => {
            if (!messageId) return undefined;
            const range = findCGRangeForParagraph(messageId, safeIndex);
            return range?.seed ?? undefined;
          })()}
          basePrompt={(() => {
            if (!messageId) return undefined;
            const range = findCGRangeForParagraph(messageId, safeIndex);
            return range?.prompt ?? undefined;
          })()}
          negativePrompt={(() => {
            const settings = loadCGSettings();
            return settings.novelAI.negativePrompt;
          })()}
          onImageUpdated={async newBase64 => {
            // 更新当前范围的 CG
            setActiveCGRange({
              ...activeCGRange,
              imageUrl: newBase64,
            });

            // 保存到 IndexedDB 缓存（持久化）
            if (messageId) {
              const { putCGImage, makeRangeCacheKey } = await import('../services/cgCache');
              const cacheKey = makeRangeCacheKey(messageId, activeCGRange.startIndex, activeCGRange.endIndex);
              await putCGImage(cacheKey, newBase64);
            }
          }}
        />
      )}

      {/* Options slide-in animation */}
      <style>{`
        @keyframes optionSlideIn {
          from {
            opacity: 0;
            transform: translateY(20px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
      `}</style>
    </div>
  );
};
