/**
 * 导演 LLM 服务
 * 负责调用独立配置的 LLM 分析文本，决定 CG 插入位置并生成画面描述 tags
 */

import {
  DEFAULT_DIRECTOR_CONTRACT_RANGE,
  DEFAULT_DIRECTOR_CONTRACT_SINGLE,
  DEFAULT_DIRECTOR_JAILBREAK,
  DEFAULT_DIRECTOR_SPEC,
  DEFAULT_DIRECTOR_THINKING,
} from '../constants';
import type { DirectorAnalysisItem, DirectorLLMConfig, DirectorRangeAnalysisItem } from '../types';

/** 单次请求超时（毫秒）- 设为 0 表示不限制超时，让 API 自然完成或失败 */
const REQUEST_TIMEOUT_MS = 300000; // 300 秒超时（5 分钟）- 手机网络可能较慢
/** 网络错误时的最大重试次数（不含首次） */
const MAX_RETRIES = 2;
/** 重试基础延迟（毫秒），按指数回退 */
const RETRY_BASE_DELAY_MS = 1500;

/**
 * 采样温度。这个任务是「结构化选段 + 固定格式输出」，属于低随机性任务：
 * 温度偏高会让同一段正文在两次请求间漂出不同的区间与数量（实测要求「恰好 1 个」时曾返回 4 个）。
 * 0.3 保留少量措辞弹性，同时让选段与数量稳定可复现。
 */
const DIRECTOR_LLM_TEMPERATURE = 0.3;

/** 单次请求可承载的段落数上限；超过则认为一次性分析不可靠，直接分批 */
const SINGLE_REQUEST_MAX = 400;

/** 分批分析时每批最多段落数 */
const BATCH_SIZE = 150;

/**
 * 规范化 endpoint：确保以 /chat/completions 结尾，并去除首尾空格
 */
function normalizeEndpoint(raw: string): string {
  let endpoint = raw.trim(); // 去除首尾空格
  if (endpoint.endsWith('/chat/completions')) return endpoint;
  if (!endpoint.endsWith('/')) endpoint += '/';
  if (endpoint.endsWith('/v1/')) {
    endpoint += 'chat/completions';
  } else {
    endpoint += 'v1/chat/completions';
  }
  return endpoint;
}

/** 判断错误是否值得重试（网络层错误或 5xx） */
function isRetriableError(err: unknown): boolean {
  if (err instanceof Error) {
    // AbortError 来自我们自己的超时，按网络问题处理
    if (err.name === 'AbortError') return true;
    // fetch 网络层失败 (DNS / 连接被拒 / 超时 / CORS) 在浏览器里表现为 TypeError: Failed to fetch
    if (err.name === 'TypeError' && /failed to fetch|network|load failed/i.test(err.message)) return true;
    // 我们抛出的带 5xx 的错误
    if (/^导演 LLM 请求失败 \(5\d{2}\)/.test(err.message)) return true;
  }
  return false;
}

/** 把底层 fetch 错误转成更易读的中文错误 */
function humanizeFetchError(err: unknown, endpoint: string): Error {
  if (err instanceof Error) {
    if (err.name === 'AbortError') {
      return new Error(
        `导演 LLM 请求超时（>${REQUEST_TIMEOUT_MS / 1000}s）：无法连接 ${endpoint}，请检查网络或更换中转站`,
      );
    }
    if (err.name === 'TypeError' && /failed to fetch|network|load failed/i.test(err.message)) {
      return new Error(
        `导演 LLM 网络错误：${endpoint}\n` +
          `原始错误: ${err.message}\n` +
          `可能原因：\n` +
          `1. CORS 跨域问题（请确保 API 服务器允许跨域）\n` +
          `2. 网络连接失败（DNS 无法解析或服务器不可达）\n` +
          `3. 防火墙或代理拦截\n` +
          `4. API endpoint 地址错误\n` +
          `建议：在浏览器控制台查看详细的网络错误`,
      );
    }
    // 如果已经是我们自己包装的错误，直接返回
    return err;
  }
  return new Error(`导演 LLM 未知错误: ${String(err)}`);
}

/**
 * 提示词调试开关。三处任一为真即开：
 *   ① 设置的 directorLLM.debugPrompt
 *   ② 控制台 globalThis.__VNUI_DEBUG_PROMPT__ = true（本次会话）
 *   ③ localStorage.vnui_debug_prompt = '1'（持久；iframe 为 opaque origin 时读取会抛错，已忽略）
 * 正常流程一条日志都不打：请求 messages、模型原始返回、解析结果都只在此开关打开时输出。
 */
function isPromptDebugEnabled(config: DirectorLLMConfig): boolean {
  if (config.debugPrompt === true) return true;
  if ((globalThis as Record<string, unknown>).__VNUI_DEBUG_PROMPT__ === true) return true;
  try {
    return globalThis.localStorage?.getItem('vnui_debug_prompt') === '1';
  } catch {
    return false;
  }
}

/** 把 messages 逐条打成可直接复制的纯文本（避免 DevTools 把长对象折叠成需要逐层展开）。 */
function logPromptDebug(body: Record<string, unknown>, endpoint: string): void {
  const messages = Array.isArray(body.messages)
    ? (body.messages as Array<{ role?: string; content?: string }>)
    : [];
  console.groupCollapsed(
    `[directorLLM][debug] 请求 → ${endpoint}（${messages.length} 条消息，model=${String(body.model)}）`,
  );
  console.log(
    `temperature=${String(body.temperature)}  max_tokens=${String(body.max_tokens)}  messages=${messages.length}`,
  );
  messages.forEach((message, index) => {
    console.log(`--- #${index} ${message.role ?? '?'}（${(message.content ?? '').length} 字符）---\n${message.content ?? ''}`);
  });
  console.groupEnd();
}

/**
 * 共享的 LLM 请求函数：带超时 + 有限重试 + 错误转译
 * 返回 LLM 输出的纯文本 content
 * @param signal 可选的 AbortSignal，用于外部中断请求
 */
async function callDirectorLLMAPI(
  config: DirectorLLMConfig,
  requestBody: object,
  signal?: AbortSignal,
): Promise<string> {
  const endpoint = normalizeEndpoint(config.endpoint);
  const body: Record<string, unknown> = requestBody as Record<string, unknown>;
  // content 为空（答案落进推理通道）时只强制重试一次，避免与 5xx 重试叠加拿光次数
  let emptyContentRetried = false;
  const debug = isPromptDebugEnabled(config);

  let lastError: unknown;
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;

    // 只有在设置了超时时间时才启用超时
    if (REQUEST_TIMEOUT_MS > 0) {
      timer = setTimeout(() => {
        controller.abort();
      }, REQUEST_TIMEOUT_MS);
    }

    // 如果外部 signal 已经中止，直接抛出
    if (signal?.aborted) {
      if (timer) clearTimeout(timer);
      throw new Error('请求已被外部中止');
    }

    // 监听外部 signal 的中止事件
    const externalAbortHandler = () => {
      controller.abort();
    };
    signal?.addEventListener('abort', externalAbortHandler);

    try {
      if (debug) logPromptDebug(body, endpoint);
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${config.apiKey}`,
        },
        body: JSON.stringify(body),
        signal: controller.signal,
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => '');
        console.error(`[directorLLM] 错误响应 body:`, errorText);
        const err = new Error(`导演 LLM 请求失败 (${response.status}): ${errorText || response.statusText}`);

        // 5xx 才重试，4xx 直接抛
        if (response.status >= 500 && attempt < MAX_RETRIES) {
          lastError = err;
          await new Promise(r => setTimeout(r, RETRY_BASE_DELAY_MS * Math.pow(2, attempt)));
          continue;
        }
        throw err;
      }

      const responseText = await response.text();

      let data;
      try {
        data = JSON.parse(responseText);
      } catch (parseErr) {
        console.error(`[directorLLM] JSON 解析失败:`, parseErr);
        console.error(`[directorLLM] 原始响应:`, responseText);
        throw new Error(`导演 LLM 返回的不是有效 JSON: ${parseErr}`);
      }

      // 支持标准 OpenAI 格式和 DeepSeek 推理模型格式
      const message = data?.choices?.[0]?.message;
      const content = typeof message?.content === 'string' ? message.content : '';
      const reasoning = typeof message?.reasoning_content === 'string' ? message.reasoning_content : '';
      const finishReason = data?.choices?.[0]?.finish_reason;

      if (!content.trim()) {
        // 截断优先判定：内容为空且被截断时重试没有意义
        if (finishReason === 'length') {
          throw new Error('导演 LLM 响应被截断（finish_reason: length）\n建议：增加 max_tokens 参数或简化输入文本');
        }

        // content 为空：答案很可能落进了 reasoning 通道。那不是「最终答案」——可能只是中间草稿，
        // 也可能尚未执行数量等收尾约束（实测出现过要求「恰好 1 个」却返回 4 个）。先原样重试一次。
        if (!emptyContentRetried) {
          emptyContentRetried = true;
          console.warn('[directorLLM] content 为空（答案疑似落进 reasoning_content），已原样重试一次');
          continue;
        }

        // 重试后仍为空：只能退回 reasoning_content，但必须显式告知，不再假装这是正常响应
        if (reasoning.trim()) {
          console.warn(
            '[directorLLM] 重试后 content 仍为空，退回使用 reasoning_content 作为答案；其内容可能不完整或未执行数量等收尾约束',
          );
          if (debug) {
            console.groupCollapsed(
              `[directorLLM][debug] 响应（回退 reasoning_content）← ${reasoning.length} 字符` +
                (finishReason ? ` / finish_reason: ${finishReason}` : ''),
            );
            console.log(reasoning);
            console.groupEnd();
          }
          return reasoning;
        }

        console.error(`[directorLLM] 响应结构异常，完整数据:`, data);
        console.error(`[directorLLM] choices 数组:`, data?.choices);
        console.error(`[directorLLM] message:`, message);
        throw new Error('导演 LLM 返回内容为空或结构不符合预期');
      }

      if (debug) {
        // 同时暴露 reasoning_content 与 finish_reason：否则「思考没跑」和「思考跑了但看不见」无法区分
        const hasThinkingBlock = /<think(?:ing)?\b/i.test(content);
        console.groupCollapsed(
          `[directorLLM][debug] 响应 ← content ${content.length} 字符` +
            ` / <thinking> ${hasThinkingBlock ? '有' : '无'}` +
            ` / reasoning_content ${reasoning ? `${reasoning.length} 字符` : '无'}` +
            (finishReason ? ` / finish_reason: ${finishReason}` : ''),
        );
        console.log(content);
        if (reasoning) {
          console.log('--- reasoning_content（推理模型的内部思考，本次未参与解析）---');
          console.log(reasoning);
        }
        console.groupEnd();
      }
      return content;
    } catch (e) {
      lastError = e;

      if (attempt < MAX_RETRIES && isRetriableError(e)) {
        const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
        await new Promise(r => setTimeout(r, delay));
        continue;
      }
      throw humanizeFetchError(e, endpoint);
    } finally {
      clearTimeout(timer);
      signal?.removeEventListener('abort', externalAbortHandler);
    }
  }

  // 兜底（理论上不会走到）
  throw humanizeFetchError(lastError, endpoint);
}

/** 取预设值；留空或全为空白时回落内置默认。 */
function presetValue(value: string | undefined, fallback: string): string {
  return (value ?? '').trim() || fallback;
}

/** 按 min/max 生成数量规则文本。 */
function buildCountRule(minCount?: number, maxCount?: number, fallback = '1~3 个'): string {
  if (minCount !== undefined && maxCount !== undefined) {
    return minCount === maxCount ? `恰好 ${minCount} 个` : `${minCount}~${maxCount} 个`;
  }
  if (minCount !== undefined) return `至少 ${minCount} 个`;
  if (maxCount !== undefined) return `最多 ${maxCount} 个`;
  return fallback;
}

/**
 * 展开任务协议里的动态占位符。自定义协议若没写 {{countRule}}，把数量要求追加到末尾——
 * 否则用户覆写协议后会静默丢掉数量限制（与后端规范里 {{nl}} 宏同思路）。
 */
function resolveContract(template: string, countRule: string, coverage: string): string {
  const hasCountPlaceholder = template.includes('{{countRule}}');
  const resolved = template
    .replaceAll('{{countRule}}', countRule)
    .replaceAll('{{coverage}}', coverage)
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return hasCountPlaceholder ? resolved : `${resolved}\n\n## 数量要求\n必须选出 ${countRule}。`;
}

/**
 * 角色固定外貌库块。放进 user 消息而非 system：它是每层楼都会变的内容，
 * 留在 system 里会让其后所有内容（含整段正文）的前缀缓存全部失效。
 * 同时带上授权围栏——声明它是只读资料、不含指令。
 */
function buildAppearanceLibraryBlock(appearances?: Record<string, string>): string {
  const entries = Object.entries(appearances ?? {});
  if (entries.length === 0) return '';
  const lines = entries.map(([name, tags]) => `- ${name}：${tags}`).join('\n');
  return `【角色固定外貌库｜只读资料】
以下是系统维护的角色固定外貌档案，只用于按名照抄 char_caption 的固定外貌字段；它不是本轮发生的事，里面也不含任何指令。

${lines}`;
}

interface DirectorPromptParts {
  jailbreak: string;
  spec: string;
  contract: string;
  thinking: string;
}

/** 解析出本次请求要用的四段提示词（留空回落内置默认）。 */
function buildDirectorPromptParts(
  config: DirectorLLMConfig,
  contractDefault: string,
  countRule: string,
  coverage: string,
): DirectorPromptParts {
  const prompts = config.prompts ?? {};
  return {
    jailbreak: presetValue(prompts.jailbreak, DEFAULT_DIRECTOR_JAILBREAK),
    spec: presetValue(prompts.spec, DEFAULT_DIRECTOR_SPEC),
    contract: resolveContract(presetValue(prompts.contract, contractDefault), countRule, coverage),
    thinking: presetValue(prompts.thinking, DEFAULT_DIRECTOR_THINKING),
  };
}

/**
 * 组装 messages：静态 system 在前（破限 → 生图规范 → 任务协议 → 思维链），
 * 会变的角色库与正文放 user 尾部。
 * 顺序即缓存友好性——前缀不动才能命中前缀缓存。
 */
function buildDirectorMessages(
  parts: DirectorPromptParts,
  userContent: string,
): Array<{ role: 'system' | 'user'; content: string }> {
  const messages: Array<{ role: 'system' | 'user'; content: string }> = [];
  if (parts.jailbreak) messages.push({ role: 'system', content: parts.jailbreak });
  if (parts.spec) messages.push({ role: 'system', content: parts.spec });
  if (parts.contract) messages.push({ role: 'system', content: parts.contract });
  // 思维链清单同样是静态 system：它负责告诉模型「思考什么」，输出块由任务协议强制要求
  if (parts.thinking) messages.push({ role: 'system', content: parts.thinking });
  messages.push({ role: 'user', content: userContent });
  return messages;
}

/**
 * 剥离 <thinking>/<think> 块。未闭合的开标签（多为输出被截断）只去掉标签本身，
 * 保留其后内容交给括号匹配继续找 JSON。
 */
function stripThinking(raw: string): string {
  return String(raw ?? '')
    .replace(/<think(?:ing)?\b[\s\S]*?<\/think(?:ing)?>/gi, '')
    .replace(/<\/?think(?:ing)?\b[^>]*>/gi, '')
    .trim();
}

/**
 * 抽取候选 JSON 值：代码块优先，再按括号深度（带字符串/转义状态）逐个抠出顶层 [..] / {..}。
 * 深度匹配能正确处理嵌套对象——旧版正则用 [^{}]* 无法跨越 {，characters 一非空就整体失效。
 * 本函数不做思维链剥离，剥离与兜底顺序由调用方决定。
 */
function collectJsonCandidates(source: string): unknown[] {
  const texts: string[] = [];
  for (const match of source.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)) texts.push(match[1].trim());
  texts.push(source);

  const values: unknown[] = [];
  for (const text of texts) {
    for (let start = 0; start < text.length; start += 1) {
      const open = text[start];
      if (open !== '[' && open !== '{') continue;
      const close = open === '[' ? ']' : '}';
      let depth = 0;
      let quoted = false;
      let escaped = false;
      for (let index = start; index < text.length; index += 1) {
        const char = text[index];
        if (quoted) {
          if (escaped) escaped = false;
          else if (char === '\\') escaped = true;
          else if (char === '"') quoted = false;
          continue;
        }
        if (char === '"') quoted = true;
        else if (char === open) depth += 1;
        else if (char === close && --depth === 0) {
          try {
            values.push(JSON.parse(text.slice(start, index + 1)));
          } catch {
            // 该片段不是合法 JSON，继续扫下一个起始括号
          }
          start = index;
          break;
        }
      }
    }
  }
  return values;
}

/**
 * 从 LLM 返回文本中提取分析结果；逐个候选尝试，取第一个能筛出有效条目的。
 * 剥思维链后的候选优先；一无所获时退回原文——模型把最终 JSON 也写进 <thinking> 块内时，
 * 无条件剥离会把答案一起剥掉，这层兜底能把它捞回来（思考里的草稿 JSON 通不过校验，不会误取）。
 */
function extractJsonFromResponse(text: string): DirectorAnalysisItem[] {
  const candidates = [...collectJsonCandidates(stripThinking(text)), ...collectJsonCandidates(text)];
  for (const value of candidates) {
    const list = Array.isArray(value) ? value : [value];
    const items = list.filter(isValidItem);
    if (items.length > 0) return items;
  }
  return [];
}

/** 校验单个分析结果是否有效 */
function isValidItem(item: any): item is DirectorAnalysisItem {
  return (
    item &&
    typeof item.paragraphIndex === 'number' &&
    Number.isInteger(item.paragraphIndex) &&
    item.paragraphIndex >= 0 &&
    typeof item.tags === 'string' &&
    item.tags.trim().length > 0
  );
}

/**
 * 调用导演 LLM 分析文本段落
 * @param paragraphs 文本段落数组
 * @param config 导演 LLM 配置
 * @returns 分析结果数组
 */
export async function analyzeWithDirectorLLM(
  paragraphs: string[],
  config: DirectorLLMConfig,
  characterAppearances?: Record<string, string>,
): Promise<DirectorAnalysisItem[]> {
  if (!config.endpoint || !config.apiKey || !config.model) {
    throw new Error('导演 LLM 配置不完整：请检查 endpoint、apiKey 和 model');
  }

  const countRule = buildCountRule(config.minCGCount, config.maxCGCount, '1~3 个');
  const parts = buildDirectorPromptParts(config, DEFAULT_DIRECTOR_CONTRACT_SINGLE, countRule, '');
  const libraryBlock = buildAppearanceLibraryBlock(characterAppearances);

  // 用户消息：变化的角色库在前、带索引的段落列表在后；静态段全部留在 system 里以命中前缀缓存
  const userMessage = paragraphs.map((p, i) => `[${i}] ${p}`).join('\n\n');
  const userContent =
    (libraryBlock ? `${libraryBlock}\n\n` : '') +
    `请分析以下段落，选出适合配 CG 的段落并生成画面标签：\n\n${userMessage}`;

  const requestBody = {
    model: config.model,
    messages: buildDirectorMessages(parts, userContent),
    temperature: DIRECTOR_LLM_TEMPERATURE,
    max_tokens: 8000, // 增加到 8000 以支持 DeepSeek 等推理模型
  };

  // 调用共享 API 函数（带超时 + 重试）
  const content = await callDirectorLLMAPI(config, requestBody);

  const items = extractJsonFromResponse(content);

  if (items.length === 0) {
    // 成功拿到响应却一条都没解析出来 = 静默失败，必须把原文打出来，否则用户只看到「没生成」
    console.warn('[directorLLM] 未从响应中解析出有效条目，模型原始返回如下：');
    console.warn(content);
  } else if (isPromptDebugEnabled(config)) {
    console.log(`[directorLLM][debug] 解析出 ${items.length} 项`, items);
  }

  // 过滤掉超出段落范围的索引，再清洗 tags / characters（去中文、规范化 centers、核对人数）
  const validItems = items
    .filter(item => item.paragraphIndex < paragraphs.length)
    .map((item, index) => sanitizeAnalysisItem(item, `结果[${index}]`));

  // 应用数量限制（如果设置了）
  if (config.maxCGCount !== undefined && validItems.length > config.maxCGCount) {
    // 超出数量要求属于模型违规，静默截断会让问题永远不可见（实测要求「恰好 1 个」时返回过 4 个）
    console.warn(
      `[directorLLM] 模型返回 ${validItems.length} 个，超过上限 ${config.maxCGCount}，已截断为前 ${config.maxCGCount} 个`,
    );
    return validItems.slice(0, config.maxCGCount);
  }

  return validItems;
}

// ====== 范围版本（新增）======

/**
 * 计算范围版的数量规则与全CG覆盖指令。
 * 全CG模式下忽略最小值限制、保留最大值；普通模式按用户配置。
 */
function buildRangeCountRule(
  minCount: number | undefined,
  maxCount: number | undefined,
  fullCoverageMode: boolean,
): { countRule: string; coverage: string } {
  const countRule = fullCoverageMode
    ? maxCount !== undefined
      ? `最多 ${maxCount} 个`
      : '适量'
    : buildCountRule(minCount, maxCount, '1~2 个');
  const coverage = fullCoverageMode
    ? '⚠️ **全CG覆盖模式**：你必须确保所有段落（从第一段到最后一段）都被 CG 范围覆盖，不允许有任何段落没有 CG。相邻的相似场景可以合并为同一个 CG 范围以减少生成数量，但不能留下空白段落。'
    : '';
  return { countRule, coverage };
}

/** 从 LLM 返回文本中提取范围分析结果；与单段落版同口径（剥思维链优先，原文兜底）。 */
function extractRangeJsonFromResponse(text: string): DirectorRangeAnalysisItem[] {
  const candidates = [...collectJsonCandidates(stripThinking(text)), ...collectJsonCandidates(text)];
  for (const value of candidates) {
    const list = Array.isArray(value) ? value : [value];
    const items = list.filter(isValidRangeItem);
    if (items.length > 0) return items;
  }
  return [];
}

/** 校验单个范围分析结果是否有效 */
function isValidRangeItem(item: any): item is DirectorRangeAnalysisItem {
  return (
    item &&
    typeof item.startIndex === 'number' &&
    typeof item.endIndex === 'number' &&
    Number.isInteger(item.startIndex) &&
    Number.isInteger(item.endIndex) &&
    item.startIndex >= 0 &&
    item.endIndex >= item.startIndex &&
    typeof item.tags === 'string' &&
    item.tags.trim().length > 0
  );
}

/** 中日韩文字与全角标点：这些字符进 NovelAI 只会变成垃圾 token。 */
const CJK_PATTERN = /[\u3000-\u303f\u3400-\u4dbf\u4e00-\u9fff\uff00-\uffef]/;

/**
 * 剔除 tag 串里含中日韩文字的逗号分隔片段。
 * 只用于要直接发给 NovelAI 的字段（tags / char_caption）；reason 是中文说明字段，不经过这里。
 */
function stripCjkTags(value: string, label: string): string {
  const removed: string[] = [];
  const kept = value
    .split(',')
    .map(part => part.trim())
    .filter(part => {
      if (!part) return false;
      if (CJK_PATTERN.test(part)) {
        removed.push(part);
        return false;
      }
      return true;
    });
  if (removed.length > 0) {
    console.warn(`[directorLLM] ${label} 含中文片段，已剔除（中文 tag 进 NovelAI 只会变成垃圾 token）：`, removed);
  }
  return kept.join(', ');
}

/** 把坐标夹回 [0,1]；缺失或非有限数回落到画面中心 0.5。 */
function normalizeCenter(value: unknown): { x: number; y: number } {
  const point = (value ?? {}) as { x?: unknown; y?: unknown };
  const clamp = (n: unknown): number => {
    const num = typeof n === 'number' && Number.isFinite(n) ? n : 0.5;
    return Math.min(1, Math.max(0, num));
  };
  return { x: clamp(point.x), y: clamp(point.y) };
}

/**
 * 规范化角色数组。
 *
 * novelAI.ts:296 的 snapCentersToGrid 会对 centers 直接 .map()：缺失或非数组会抛 TypeError
 * 让整张图生成失败，坐标是非数字则算出 NaN 污染请求。所以这里必须保证
 * 「数组 + 非空字符串 char_caption + 合法的 0~1 坐标数组」。
 */
function normalizeCharacters(
  characters: unknown,
  label: string,
): Array<{ char_caption: string; centers: Array<{ x: number; y: number }> }> {
  if (!Array.isArray(characters)) {
    if (characters !== undefined && characters !== null) {
      console.warn(`[directorLLM] ${label} 的 characters 不是数组，已丢弃`);
    }
    return [];
  }
  const normalized: Array<{ char_caption: string; centers: Array<{ x: number; y: number }> }> = [];
  characters.forEach((entry, index) => {
    const character = (entry ?? {}) as { char_caption?: unknown; centers?: unknown };
    const charCaption =
      typeof character.char_caption === 'string'
        ? stripCjkTags(character.char_caption, `${label}.characters[${index}].char_caption`)
        : '';
    if (!charCaption) {
      console.warn(`[directorLLM] ${label}.characters[${index}] 缺 char_caption，已丢弃该角色`);
      return;
    }
    const hasCenters = Array.isArray(character.centers) && character.centers.length > 0;
    if (!hasCenters) {
      console.warn(`[directorLLM] ${label}.characters[${index}] 的 centers 缺失或非法，已回退到画面中心`);
    }
    normalized.push({
      char_caption: charCaption,
      centers: hasCenters ? (character.centers as unknown[]).map(normalizeCenter) : [{ x: 0.5, y: 0.5 }],
    });
  });
  return normalized;
}

/** 从人数 tag 里数出声明的人数（1girl / 2boys / 1girl 1boy …）。 */
function countDeclaredPeople(tags: string): number {
  let total = 0;
  for (const match of tags.matchAll(/(\d+)\s*(?:girl|boy|other)s?\b/gi)) total += Number(match[1]);
  return total;
}

/** 统一清洗一条分析结果：tags / char_caption 去中文，characters 规范化，并核对人数一致性。 */
function sanitizeAnalysisItem(item: any, label: string): any {
  const tags = typeof item?.tags === 'string' ? stripCjkTags(item.tags, `${label}.tags`) : item?.tags;
  const characters = normalizeCharacters(item?.characters, label);
  if (typeof tags === 'string') {
    const declared = countDeclaredPeople(tags);
    if (declared !== characters.length) {
      console.warn(
        `[directorLLM] ${label} 人数 tag 声明 ${declared} 人、characters 实际 ${characters.length} 人，不一致会导致漏画或多画`,
      );
    }
  }
  // 可选字段必须先删掉 {...item} 带进来的原始值、再按需写回：
  // 否则模型给的非法值（中文片段、非字符串）会原样流到下游。
  const sanitized = { ...item, tags, characters } as Record<string, unknown>;

  const negative =
    typeof item?.negative === 'string' ? stripCjkTags(item.negative, `${label}.negative`).trim() : '';
  if (negative) sanitized.negative = negative;
  else delete sanitized.negative;

  // 出图比例已固定为配置的分辨率，忽略模型可能残留的 size 字段
  delete sanitized.size;

  return sanitized;
}

/**
 * 对一批段落调用导演 LLM 并解析结果。
 * 提示词用**本批的局部索引**（从 0 开始，模型对从 0 开始的列表最稳），
 * 解析后再换算成整层楼的全局索引返回，供跨批合并。
 * @param chunk 本批段落
 * @param rangeStart 本批第一段的全局索引（含）
 */
async function requestRangeAnalysis(params: {
  chunk: string[];
  rangeStart: number;
  config: DirectorLLMConfig;
  parts: DirectorPromptParts;
  characterAppearances?: Record<string, string>;
  signal?: AbortSignal;
}): Promise<DirectorRangeAnalysisItem[]> {
  const libraryBlock = buildAppearanceLibraryBlock(params.characterAppearances);
  // 用户消息：变化的角色库在前、带索引的段落列表在后；静态段全部留在 system 里以命中前缀缓存
  const userMessage = params.chunk.map((paragraph, index) => `[${index}] ${paragraph}`).join('\n\n');
  const userContent =
    (libraryBlock ? `${libraryBlock}\n\n` : '') +
    `请分析以下段落，标记出适合配 CG 的段落范围并生成画面标签：\n\n${userMessage}`;

  const requestBody = {
    model: params.config.model,
    messages: buildDirectorMessages(params.parts, userContent),
    temperature: DIRECTOR_LLM_TEMPERATURE,
    max_tokens: 8000, // 增加到 8000 以支持 DeepSeek 等推理模型
  };

  // 调用共享 API 函数（带超时 + 重试）
  const content = await callDirectorLLMAPI(params.config, requestBody, params.signal);
  const items = extractRangeJsonFromResponse(content);

  if (items.length === 0) {
    // 成功拿到响应却一条都没解析出来 = 静默失败，必须把原文打出来，否则用户只看到「没生成」
    console.warn('[directorLLM] 未从响应中解析出有效条目，模型原始返回如下：');
    console.warn(content);
  } else if (isPromptDebugEnabled(params.config)) {
    console.log(`[directorLLM][debug] 解析出 ${items.length} 项`, items);
  }

  // 校验局部索引 → 清洗 tags / characters（去中文、规范化 centers、核对人数）→ 换算成全局索引。
  // 只接受起点落在本批内的区间，并把终点夹回本批末尾，避免跨批重复或引用不存在的段落。
  const chunkLength = params.chunk.length;
  return items
    .filter(item => item.startIndex >= 0 && item.startIndex < chunkLength)
    .map(item => ({ ...item, endIndex: Math.min(item.endIndex, chunkLength - 1) }))
    .filter(item => item.endIndex >= item.startIndex)
    .map((item, index) => {
      const sanitized = sanitizeAnalysisItem(item, `结果[${index}]`);
      return {
        ...sanitized,
        startIndex: sanitized.startIndex + params.rangeStart,
        endIndex: sanitized.endIndex + params.rangeStart,
      } as DirectorRangeAnalysisItem;
    });
}

/**
 * 判断返回的范围是否覆盖了全部段落（全CG覆盖模式下用于判断是否需要降级为分批）。
 */
function coversAllParagraphs(items: DirectorRangeAnalysisItem[], total: number): boolean {
  if (total <= 0) return true;
  const covered = new Uint8Array(total);
  for (const item of items) {
    const start = Math.max(0, item.startIndex);
    const end = Math.min(total - 1, item.endIndex);
    for (let index = start; index <= end; index += 1) covered[index] = 1;
  }
  return covered.every(value => value === 1);
}

/**
 * 分批分析整层楼并合并结果（每批最多 BATCH_SIZE 段）。
 * 仅用于「一次请求装不下」或「一次请求结果为空 / 覆盖不全」时的兜底。
 */
async function analyzeRangeBatched(
  paragraphs: string[],
  config: DirectorLLMConfig,
  parts: DirectorPromptParts,
  characterAppearances: Record<string, string> | undefined,
  signal: AbortSignal | undefined,
  onNotice: ((message: string) => void) | undefined,
): Promise<DirectorRangeAnalysisItem[]> {
  const batchCount = Math.ceil(paragraphs.length / BATCH_SIZE);
  console.info(`[directorLLM] 楼层共 ${paragraphs.length} 段，分 ${batchCount} 批分析以覆盖全文`);
  const merged: DirectorRangeAnalysisItem[] = [];
  const emptyBatches: string[] = [];

  for (let start = 0; start < paragraphs.length; start += BATCH_SIZE) {
    if (signal?.aborted) break;
    const end = Math.min(start + BATCH_SIZE, paragraphs.length) - 1;
    const batchItems = await requestRangeAnalysis({
      chunk: paragraphs.slice(start, end + 1),
      rangeStart: start,
      config,
      parts,
      characterAppearances,
      signal,
    });
    if (batchItems.length === 0) {
      emptyBatches.push(`#${start}-${end}`);
    }
    merged.push(...batchItems);
  }

  // 按全局索引排序，保证生成顺序与剧情顺序一致
  merged.sort((a, b) => a.startIndex - b.startIndex || a.endIndex - b.endIndex);

  // 某批没解析出任何范围 = 那部分内容不会配图，属于静默的内容损失，必须让用户看到
  if (emptyBatches.length > 0) {
    const notice = `段落 ${emptyBatches.join('、')} 未解析出 CG 范围，这部分内容不会配 CG。`;
    console.warn(`[directorLLM] ${notice}`);
    onNotice?.(notice);
  }

  return merged;
}

/**
 * 调用导演 LLM 分析文本段落（范围版本）
 *
 * 默认**整层楼一次请求发完**；只有超出单次可承载上限，或一次请求结果为空 / 覆盖不全时，才降级为分批。
 * @param paragraphs 文本段落数组
 * @param config 导演 LLM 配置
 * @param characterAppearances 角色外貌描述
 * @param signal 可选的 AbortSignal
 * @param fullCoverageMode 全CG模式：所有段落都必须被CG覆盖
 * @param onNotice 可选：需要让用户看到的非致命提示（如某批段落未解析出 CG 范围）
 * @returns 范围分析结果数组
 */
export async function analyzeWithDirectorLLMRange(
  paragraphs: string[],
  config: DirectorLLMConfig,
  characterAppearances?: Record<string, string>,
  signal?: AbortSignal,
  fullCoverageMode?: boolean,
  onNotice?: (message: string) => void,
): Promise<DirectorRangeAnalysisItem[]> {
  if (!config.endpoint || !config.apiKey || !config.model) {
    throw new Error('导演 LLM 配置不完整：请检查 endpoint、apiKey 和 model');
  }

  if (paragraphs.length === 0) return [];

  const { countRule, coverage } = buildRangeCountRule(
    config.minCGCount,
    config.maxCGCount,
    fullCoverageMode ?? false,
  );
  const parts = buildDirectorPromptParts(config, DEFAULT_DIRECTOR_CONTRACT_RANGE, countRule, coverage);

  let validItems: DirectorRangeAnalysisItem[];

  if (paragraphs.length > SINGLE_REQUEST_MAX) {
    validItems = await analyzeRangeBatched(paragraphs, config, parts, characterAppearances, signal, onNotice);
  } else {
    // 先尝试一次发完全部段落
    const single = await requestRangeAnalysis({
      chunk: paragraphs,
      rangeStart: 0,
      config,
      parts,
      characterAppearances,
      signal,
    });
    const coverageOk = !(fullCoverageMode ?? false) || coversAllParagraphs(single, paragraphs.length);

    if (single.length > 0 && coverageOk) {
      validItems = single;
    } else if (paragraphs.length > BATCH_SIZE) {
      // 一次请求为空（多因被 max_tokens 截断）或覆盖不全 → 分批重来，避免整层丢 CG
      console.warn('[directorLLM] 一次请求结果为空或覆盖不全，改为分批分析');
      validItems = await analyzeRangeBatched(paragraphs, config, parts, characterAppearances, signal, onNotice);
    } else {
      validItems = single;
    }
  }

  // 应用数量限制（如果设置了）。全CG覆盖模式下不截断：截断会砍掉后半层，重新出现空白段落。
  const skipTruncation = fullCoverageMode ?? false;
  if (!skipTruncation && config.maxCGCount !== undefined && validItems.length > config.maxCGCount) {
    // 超出数量要求属于模型违规，静默截断会让问题永远不可见（实测要求「恰好 1 个」时返回过 4 个）
    console.warn(
      `[directorLLM] 模型返回 ${validItems.length} 个，超过上限 ${config.maxCGCount}，已截断为前 ${config.maxCGCount} 个`,
    );
    return validItems.slice(0, config.maxCGCount);
  }

  return validItems;
}
