/**
 * NovelAI 模型能力表（单一真源）
 * 请求层（novelAI.ts）与界面层（CGConfigScreen.tsx）都从这里读取模型能力，
 * 保证「界面显示/禁用」与「请求裁剪」永远一致。
 *
 * 能力依据 NovelAI API 及社区 SDK（caru-ini/novelai-sdk）整理。
 */

/** 模型档位（能力族） */
export type NovelAIModelFamily = 'v5' | 'v4.5' | 'v4' | 'v3';

/** 能力档位下拉的取值：自动推断或手动指定 */
export type NovelAIModelFamilyOverride = NovelAIModelFamily | 'auto';

/** 单个模型的能力描述 */
export interface NovelAIModelCapabilities {
  id: string;
  label: string;
  family: NovelAIModelFamily;
  /** 是否使用 v4_prompt / v4_negative_prompt 结构 */
  usesV4Prompt: boolean;
  /** params_version：v5=4，其余=3 */
  paramsVersion: number;
  /** 是否支持 Vibe Transfer（reference_image_multiple） */
  supportsVibe: boolean;
  /** 是否支持多角色（char_captions / use_coords） */
  supportsCharacters: boolean;
  /** 是否支持角色参考（director_reference_*，仅 v4.5） */
  supportsCharacterReference: boolean;
  /** 是否支持透明背景参数（straight_alpha / tag_hint_transparent_background，仅 v5） */
  supportsTransparent: boolean;
  defaultSampler: string;
  defaultScale: number;
}

/** 自定义模型 ID 时下拉框使用的哨兵值 */
export const CUSTOM_MODEL_VALUE = '__custom__';

