/** 根据模型 ID 子串推断档位（推断不出时回落 V3 legacy） */
export function inferModelFamily(modelId: string): NovelAIModelFamily {
  const id = (modelId || '').toLowerCase();
  if (id.includes('nai-diffusion-5') || id.includes('nai-5')) return 'v5';
  if (id.includes('nai-diffusion-4-5') || id.includes('nai-4.5')) return 'v4.5';
  if (id.includes('nai-diffusion-4')) return 'v4';
  return 'v3';
}

/** 查找官方模型下拉项（找不到返回 undefined，表示自定义模型） */
export function findModelOption(modelId: string): NovelAIModelOption | undefined {
  return NOVELAI_MODEL_OPTIONS.find(m => m.id === modelId);
}

/**
 * 解析模型能力：优先使用手动档位覆盖，否则按 ID 推断
 */
export function resolveModelCapabilities(
  modelId: string,
  familyOverride?: NovelAIModelFamilyOverride,
): NovelAIModelCapabilities {
  const family = familyOverride && familyOverride !== 'auto' ? familyOverride : inferModelFamily(modelId);
  const base = FAMILY_CAPABILITIES[family] ?? FAMILY_CAPABILITIES.v3;
  const option = findModelOption(modelId);
  return {
    ...base,
    id: modelId,
    label: option?.label ?? `${modelId || '自定义模型'}（${NOVELAI_FAMILY_LABELS[base.family]}）`,
  };
}

/** 一行能力摘要（用于界面展示） */
export function describeModelCapabilities(caps: NovelAIModelCapabilities): string {
  const parts: string[] = [];
  parts.push(caps.supportsCharacters ? '支持多角色' : '不支持多角色');
  parts.push(caps.supportsVibe ? '支持 Vibe 风格参考' : '不支持 Vibe 风格参考');
  if (caps.supportsCharacterReference) parts.push('支持角色参考');
  if (caps.supportsTransparent) parts.push('支持透明背景');
  return parts.join('；');
}

/**
 * 切换模型时挑选合适的采样器：
 * - 当前采样器为空或不在可用列表 → 用新模型默认采样器
 * - 当前采样器恰为上一模型档位的默认值 → 跟随新模型默认值
 * - 否则保留用户当前选择
 */
export function resolveSamplerForModel(
  modelId: string,
  familyOverride: NovelAIModelFamilyOverride | undefined,
  currentSampler: string | undefined,
  previousModelId?: string,
): string {
  const caps = resolveModelCapabilities(modelId, familyOverride);
  if (!currentSampler) return caps.defaultSampler;
  const isValid = NOVELAI_SAMPLER_OPTIONS.some(s => s.value === currentSampler);
  if (!isValid) return caps.defaultSampler;
  if (previousModelId !== undefined) {
    const prevCaps = resolveModelCapabilities(previousModelId, familyOverride);
    if (currentSampler === prevCaps.defaultSampler && prevCaps.defaultSampler !== caps.defaultSampler) {
      return caps.defaultSampler;
    }
  }
  return currentSampler;
}
