/**
 * 从 NovelAI 生成的 PNG 图片里读取元数据，转成「出图方案」可用的配置。
 *
 * NovelAI 会把生成参数写进 PNG 的 `Comment` (tEXt/iTXt) chunk，格式为 JSON，含：
 * - 正/负提示词：V4+ 在 `v4_prompt.caption.base_caption` / `v4_negative_prompt.caption.base_caption`；
 *   旧版正向在 `Description` 文本块、负向在顶层 `uc`（部分版本顶层也有 `prompt`）；
 * - 采样参数：steps / scale / sampler / cfg_rescale / width / height / ucPreset / qualityToggle；
 * - Vibe 参考：`reference_image_multiple`（编码）与对应的 information_extracted / strength 数组；
 * - 模型：`Comment.model`（部分版本）或文本块 `Source`（如 "Stable Diffusion 1D44365E"）/ `Software`。
 *
 * 明确**不导入角色提示词**（`v4_prompt.caption.char_captions` / `characterPrompts`）：
 * 角色的外貌由本项目的导演 LLM 与角色库负责，混入别处的角色描述会打架。
 */

import type { NovelAIConfig } from '../types';
import type { VibeImportEntry } from './vibeManager';
import { NOVELAI_MODEL_OPTIONS } from './novelAIModels';

export interface ImportedNovelAIMetadata {
  /** 可直接并入 NovelAIConfig 的字段（只包含元数据里确实存在的项） */
  config: Partial<NovelAIConfig>;
  /** 元数据里携带的 Vibe 参考（无则为空数组） */
  vibes: VibeImportEntry[];
  /** 元数据里存在角色提示词（仅用于提示用户「已跳过」） */
  hasCharacterPrompts: boolean;
  /** 元数据里读到的模型原始字符串（可能识别不出对应模型，仅用于提示） */
  modelRaw?: string;
}

/** 读取 PNG 的 tEXt/iTXt 文本块，返回 key → value */
function readPngTextChunks(buffer: ArrayBuffer): Map<string, string> {
  const result = new Map<string, string>();
  if (buffer.byteLength < 8) return result;
  const view = new DataView(buffer);
  const signature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  for (let index = 0; index < 8; index += 1) {
    if (view.getUint8(index) !== signature[index]) return result;
  }

  let offset = 8;
  while (offset + 12 <= buffer.byteLength) {
    const length = view.getUint32(offset);
    const type = String.fromCharCode(
      view.getUint8(offset + 4),
      view.getUint8(offset + 5),
      view.getUint8(offset + 6),
      view.getUint8(offset + 7),
    );
    if (offset + 12 + length > buffer.byteLength) break;

    if (type === 'tEXt' || type === 'iTXt') {
      const data = new Uint8Array(buffer, offset + 8, length);
      const parsed = parseTextChunk(type, data);
      if (parsed) result.set(parsed.key, parsed.value);
    }
    if (type === 'IEND') break;
    offset += 12 + length; // length(4) + type(4) + data + crc(4)
  }
  return result;
}

/** 解析单个 tEXt / iTXt chunk */
function parseTextChunk(type: string, data: Uint8Array): { key: string; value: string } | null {
  let keyEnd = 0;
  while (keyEnd < data.length && data[keyEnd] !== 0) keyEnd += 1;
  if (keyEnd >= data.length) return null;
  const key = new TextDecoder().decode(data.slice(0, keyEnd));

  if (type === 'tEXt') {
    return { key, value: new TextDecoder().decode(data.slice(keyEnd + 1)) };
  }

  // iTXt: key\0 compressionFlag(1) compressionMethod(1) languageTag\0 translatedKeyword\0 text
  let cursor = keyEnd + 1;
  const compressionFlag = data[cursor] ?? 0;
  cursor += 2; // compression flag + method
  while (cursor < data.length && data[cursor] !== 0) cursor += 1; // language tag
  cursor += 1;
  while (cursor < data.length && data[cursor] !== 0) cursor += 1; // translated keyword
  cursor += 1;
  if (compressionFlag !== 0) {
    // zlib 压缩的 iTXt 需要额外解压依赖；NovelAI 不使用，跳过即可
    console.warn('[imageMetaImport] 跳过压缩的 iTXt 块:', key);
    return null;
  }
  return { key, value: new TextDecoder().decode(data.slice(cursor)) };
}

function pickString(...values: unknown[]): string {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value;
  }
  return '';
}

function pickNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function clampNumber(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/** 从 `reference_*_multiple` 三数组里抽出 Vibe 条目 */
function extractVibes(meta: Record<string, unknown>): VibeImportEntry[] {
  const encodings = Array.isArray(meta.reference_image_multiple) ? meta.reference_image_multiple : [];
  const infos = Array.isArray(meta.reference_information_extracted_multiple)
    ? meta.reference_information_extracted_multiple
    : [];
  const strengths = Array.isArray(meta.reference_strength_multiple) ? meta.reference_strength_multiple : [];

  const vibes: VibeImportEntry[] = [];
  encodings.forEach((encoding, index) => {
    if (typeof encoding !== 'string' || !encoding) return;
    vibes.push({
      name: `Vibe ${index + 1}`,
      encoding,
      infoExtracted: clampNumber(pickNumber(infos[index]) ?? 0.7, 0, 1),
      strength: clampNumber(pickNumber(strengths[index]) ?? 0.6, 0, 1),
    });
  });
  return vibes;
}

/**
 * 把元数据里的模型字符串解析成项目已知的模型 ID。
 * 来源可能是 `model` 字段（部分版本）、`Source`（如 "Stable Diffusion 1D44365E"）、`Software`。
 * 只做保守识别：精确 ID / 精确标签 / 版本号特征；识别不出返回 undefined，绝不乱猜覆盖用户设置。
 */
export function resolveModelId(raw: string): string | undefined {
  const text = raw.trim();
  if (!text) return undefined;
  if (NOVELAI_MODEL_OPTIONS.some(option => option.id === text)) return text;
  const byLabel = NOVELAI_MODEL_OPTIONS.find(option => option.label === text);
  if (byLabel) return byLabel.id;

  // 去掉尾部的哈希："Stable Diffusion 1D44365E" → "stable diffusion"
  const name = text.replace(/\s+[A-Z0-9]+$/, '').toLowerCase();
  if (name.includes('furry')) return 'nai-diffusion-furry-3';
  if (/\bv5\b|diffusion\s*5|version\s*5/.test(name)) return 'nai-diffusion-5-full';
  if (/4[.\s-]?5/.test(name)) return 'nai-diffusion-4-5-full';
  if (/\bv4\b|diffusion\s*4|version\s*4/.test(name)) return 'nai-diffusion-4-full';
  if (/\bv3\b|diffusion\s*3|version\s*3|stable diffusion/.test(name)) return 'nai-diffusion-3';
  return undefined;
}

/** 把 NovelAI Comment JSON 映射成出图方案配置 + Vibe 条目；textChunks 提供 Description / Software / Source */
export function parseNovelAIMetadata(
  meta: Record<string, unknown>,
  textChunks?: { description?: string; software?: string; source?: string },
): ImportedNovelAIMetadata {
  const v4 = (meta.v4_prompt as { caption?: Record<string, unknown> } | undefined)?.caption;
  const v4Negative = (meta.v4_negative_prompt as { caption?: Record<string, unknown> } | undefined)?.caption;

  // V4+ 在 v4_prompt.base_caption / Comment.prompt；V3 的正向提示词只在 Description 块
  const positive = pickString(v4?.base_caption, meta.prompt, textChunks?.description);
  const negative = pickString(v4Negative?.base_caption, meta.uc);

  const config: Partial<NovelAIConfig> = {};
  if (positive) config.positivePrompt = positive;
  if (negative) config.negativePrompt = negative;

  const steps = pickNumber(meta.steps);
  if (steps !== undefined) config.steps = clampNumber(Math.round(steps), 1, 100);
  const scale = pickNumber(meta.scale);
  if (scale !== undefined) config.scale = clampNumber(scale, 0, 30);
  const sampler = pickString(meta.sampler);
  if (sampler) config.sampler = sampler;
  const cfgRescale = pickNumber(meta.cfg_rescale);
  if (cfgRescale !== undefined) config.cfgRescale = clampNumber(cfgRescale, 0, 1);
  const width = pickNumber(meta.width);
  const height = pickNumber(meta.height);
  if (width !== undefined && height !== undefined && width > 0 && height > 0) {
    config.resolution = { width: Math.round(width), height: Math.round(height) };
  }
  const ucPreset = pickNumber(meta.ucPreset);
  if (ucPreset !== undefined) config.ucPreset = clampNumber(Math.round(ucPreset), 0, 4);
  if (typeof meta.qualityToggle === 'boolean') config.qualityToggle = meta.qualityToggle;

  // 模型：Comment.model > Software/Source，逐个尝试取第一个能识别的
  const modelCandidates = [
    pickString(meta.model),
    pickString(meta.software),
    pickString(meta.source),
    pickString(textChunks?.software),
    pickString(textChunks?.source),
  ].filter(Boolean);
  let modelRaw: string | undefined;
  for (const candidate of modelCandidates) {
    const resolved = resolveModelId(candidate);
    if (resolved) {
      modelRaw = candidate;
      config.model = resolved;
      break;
    }
  }
  if (!modelRaw) modelRaw = modelCandidates[0];

  const hasCharacterPrompts =
    (Array.isArray(v4?.char_captions) && v4.char_captions.length > 0) ||
    (Array.isArray(meta.characterPrompts) && meta.characterPrompts.length > 0);

  return { config, vibes: extractVibes(meta), hasCharacterPrompts, modelRaw };
}

/** 读取一张图片文件里的 NovelAI 元数据；不是 NovelAI PNG 时返回 null */
export async function readNovelAIMetadataFromFile(file: File): Promise<ImportedNovelAIMetadata | null> {
  const buffer = await file.arrayBuffer();
  const chunks = readPngTextChunks(buffer);
  const comment = chunks.get('Comment');
  if (!comment) return null;

  let parsed: unknown;
  try {
    parsed = JSON.parse(comment);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  return parseNovelAIMetadata(parsed as Record<string, unknown>, {
    description: chunks.get('Description'),
    software: chunks.get('Software'),
    source: chunks.get('Source'),
  });
}
