import YAML from 'yaml';
import { isResourceEntryName, isVoiceConfigEntryName } from '@util/worldbookEntryNames';
import { IMAGE_PRELOAD_CONCURRENCY } from './constants';
import { DialogueSegment, ResourceConfig } from './types';
// ============ 图片预加载系统 ============

/**
 * 预加载单张图片，返回 Promise
 * 已缓存的图片会立即返回，正在加载中的会复用同一 Promise
 */
/** 预加载缓存：url -> 已加载图片（模块级单例） */
const preloadedImages = new Map<string, HTMLImageElement>();
/** 预加载缓存上限，超出按 FIFO 逐出，避免长时间会话内存无限增长 */
const PRELOAD_CACHE_MAX = 200;
/** 在途预加载 Promise：url -> Promise（并发请求同一 URL 时复用） */
const loadingPromises = new Map<string, Promise<HTMLImageElement>>();

export function preloadImage(url: string): Promise<HTMLImageElement> {
  if (!url) return Promise.resolve(new Image());

  // Already cached
  if (preloadedImages.has(url)) {
    return Promise.resolve(preloadedImages.get(url)!);
  }

  // 正在加载中，复用 Promise
  if (loadingPromises.has(url)) {
    return loadingPromises.get(url)!;
  }

  const promise = new Promise<HTMLImageElement>((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      // 超上限时逐出最早的一张，避免缓存无限增长
      if (preloadedImages.size >= PRELOAD_CACHE_MAX && !preloadedImages.has(url)) {
        const oldest = preloadedImages.keys().next().value;
        if (oldest !== undefined) preloadedImages.delete(oldest);
      }
      preloadedImages.set(url, img);
      loadingPromises.delete(url);
      resolve(img);
    };
    img.onerror = () => {
      loadingPromises.delete(url);
      reject(new Error(`Failed to preload: ${url}`));
    };
    img.src = url;
  });

  loadingPromises.set(url, promise);
  return promise;
}

/**
 * 并发预加载多张图片（简单 worker-pool）
 * 复用 preloadImage 的静态缓存与在途 Promise，失败不阻塞其它图片
 *
 * @param urls 待加载的图片 URL 列表（会自动跳过已缓存项）
 * @param concurrency 并发上限，默认 IMAGE_PRELOAD_CONCURRENCY
 * @param onProgress 每完成一张回调 (completed, total)，total 为本次实际需要加载的数量
 */
export async function preloadImageBatch(
  urls: string[],
  concurrency: number = IMAGE_PRELOAD_CONCURRENCY,
  onProgress?: (completed: number, total: number) => void,
): Promise<void> {
  const pending = urls.filter(Boolean);
  if (pending.length === 0) {
    onProgress?.(0, 0);
    return;
  }

  const total = pending.length;
  let completed = 0;
  let nextIndex = 0;
  const safeConcurrency =
    Number.isFinite(concurrency) && (concurrency as number) >= 1 ? Math.floor(concurrency as number) : 6;
  const workerCount = Math.max(1, Math.min(safeConcurrency, total));

  const runWorker = async (): Promise<void> => {
    while (true) {
      const index = nextIndex++;
      if (index >= total) return;
      const url = pending[index];
      try {
        await preloadImage(url);
      } catch (e) {
        console.warn('[resourceLoader] 图片预加载失败:', url, e);
      }
      completed++;
      try {
        onProgress?.(completed, total);
      } catch (e) {
        console.error('[resourceLoader] 图片加载进度回调异常:', e);
      }
    }
  };

  await Promise.all(Array.from({ length: workerCount }, () => runWorker()));
}

/** 只读访问已缓存图片（供预加载进度统计使用） */
export function getPreloadedImageCache(): Map<string, HTMLImageElement> {
  return preloadedImages;
}

/**
 * 根据当前段落索引，预加载前后 N 段的立绘和背景图
 * 内联资源解析逻辑以避免与 parser.ts 的循环依赖 */
export function preloadNearbySegments(
  segments: DialogueSegment[],
  currentIndex: number,
  config: ResourceConfig,
  range: number = 5,
): void {
  // 内联的资源解析：角色立绘
  const resolveChar = (charName: string, face?: string): string => {
    const charImages = config.characters[charName];
    if (!charImages) return '';
    if (face && charImages[face]) return charImages[face];
    if (charImages['默认']) return charImages['默认'];
    if (charImages['default']) return charImages['default'];
    const keys = Object.keys(charImages);
    return keys.length > 0 ? charImages[keys[0]] : '';
  };

  // 内联的资源解析：背景图（优先 bgKey，其次 bgName）
  const resolveBg = (bgName: string, bgKey?: string): string => {
    if (bgKey && config.backgrounds[bgKey]) return config.backgrounds[bgKey];
    if (bgName && config.backgrounds[bgName]) return config.backgrounds[bgName];
    return '';
  };

  // 内联的资源解析：CG 图
  const resolveCg = (cgName: string): string => config.cg[cgName] || '';

  // 前缀扫描：一次算出每个段落累积到的立绘/BG/CG 状态，正/反向读取均为 O(range)
  type SegmentResourceState = { spriteChar: string; face: string; bg: string; bgKey: string; cg: string };
  const states: SegmentResourceState[] = [];
  {
    let charName = '';
    let aboutName = '';
    let faceName = '';
    for (let i = 0; i < segments.length; i++) {
      const eff = segments[i]?.effects;
      if (eff) {
        if (eff.char) {
          charName = eff.char;
          aboutName = '';
          faceName = '';
        }
        if (eff.about) {
          aboutName = eff.about;
          faceName = '';
        }
        if (eff.face) faceName = eff.face;
      }
      states.push({
        spriteChar: aboutName || charName,
        face: faceName,
        bg: eff?.bg ?? '',
        bgKey: eff?.bgKey ?? '',
        cg: eff?.cg ?? '',
      });
    }
  }

  const start = Math.max(0, currentIndex - range);
  const end = Math.min(currentIndex + range, segments.length - 1);

  for (let i = start; i <= end; i++) {
    if (i === currentIndex) continue; // 当前段落由主渲染负责，无需预加载
    const info = states[i];
    if (!info) continue;

    if (info.spriteChar) {
      const url = resolveChar(info.spriteChar, info.face);
      if (url) preloadImage(url);
    }

    if (info.bg || info.bgKey) {
      const url = resolveBg(info.bg, info.bgKey);
      if (url) preloadImage(url);
    }

    if (info.cg) {
      const url = resolveCg(info.cg);
      if (url) preloadImage(url);
    }
  }
}

/**
 * 世界书 YAML 资源格式示例:
 *
 * ```yaml
 * 角色立绘:
 *   女主:
 *     微笑: https://example.com/heroine/smile.png
 *     疑惑: https://example.com/heroine/confused.png
 *     默认: https://example.com/heroine/default.png
 *   男主:
 *     平淡: https://example.com/hero/neutral.png
 *     默认: https://example.com/hero/default.png
 *
 * 背景图:
 *   教室: https://example.com/bg/classroom.jpg
 *   走廊: https://example.com/bg/hallway.jpg
 *
 * BGM:
 *   温柔: https://example.com/bgm/gentle.mp3
 *   紧张: https://example.com/bgm/tense.mp3
 *
 * CG:
 *   重逢: https://example.com/cg/reunion.jpg
 *   决战: https://example.com/cg/final_battle.jpg
 * ```
 */

interface RawResourceYaml {
  角色立绘?: Record<string, Record<string, string>>;
  背景图?: Record<string, string>;
  BGM?: Record<string, string>;
  CG?: Record<string, string>;
  /** 角色外貌描述 tags（用于辅助 CG 生成提示词） */
  角色外貌?: Record<string, string>;
}

/** 仅接受普通对象（排除数组/标量/null），否则回落空对象 */
function asRecord(v: unknown): Record<string, string> {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, string>) : {};
}

/**
 * 仅接受「对象的每个值也是普通对象」的嵌套映射，其余条目丢弃
 */
function asNestedRecord(v: unknown): Record<string, Record<string, string>> {
  const out: Record<string, Record<string, string>> = {};
  if (!v || typeof v !== 'object' || Array.isArray(v)) return out;
  for (const [key, value] of Object.entries(v as Record<string, unknown>)) {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      out[key] = value as Record<string, string>;
    }
  }
  return out;
}

/**
 * 将世界书 YAML 内容解析为 ResourceConfig
 */
function parseResourceYaml(yamlContent: string): ResourceConfig {
  try {
    const raw = YAML.parse(yamlContent) as RawResourceYaml;

    return {
      characters: asNestedRecord(raw?.角色立绘),
      backgrounds: asRecord(raw?.背景图),
      bgm: asRecord(raw?.BGM),
      cg: asRecord(raw?.CG),
      characterAppearances: asRecord(raw?.角色外貌),
    };
  } catch (e) {
    console.error('[visual-novel-ui] 资源 YAML 解析失败:', e);
    return { characters: {}, backgrounds: {}, bgm: {}, cg: {}, characterAppearances: {} };
  }
}

/**
 * 从角色卡绑定的世界书中查找资源条目
 *
 * 查找顺序:
 * 1. 角色卡主世界书
 * 2. 角色卡附加世界书
 * 3. 全局世界书
 */
async function findResourceEntry(): Promise<string | null> {
  try {
    // 尝试从角色卡世界书中查找
    const charWorldbooks = getCharWorldbookNames('current');
    const worldbookNames: string[] = [];

    if (charWorldbooks.primary) {
      worldbookNames.push(charWorldbooks.primary);
    }
    worldbookNames.push(...charWorldbooks.additional);

    // 也检查全局世界书
    const globalNames = getGlobalWorldbookNames();
    worldbookNames.push(...globalNames);

    // 去重
    const uniqueNames = [...new Set(worldbookNames)];

    for (const wbName of uniqueNames) {
      try {
        const entries = await getWorldbook(wbName);
        // 资源条目可以是关闭的（enabled: false），这样不会作为提示词发给 AI 浪费 token
        // getWorldbook 能读到所有条目（无论开关），所以这里不检查 enabled
        const resourceEntry = entries.find(entry => isResourceEntryName(entry.name));
        if (resourceEntry && resourceEntry.content) {
          return resourceEntry.content;
        }
      } catch (e) {
        // 跳过无法访问的世界书
        continue;
      }
    }

    console.warn('[visual-novel-ui] 未在任何世界书中找到资源条目');
    return null;
  } catch (e) {
    console.error('[visual-novel-ui] 查找资源条目时出错:', e);
    return null;
  }
}

/**
 * 从世界书中查找语音配置条目 [res]角色语音
 */
async function findVoiceConfigEntry(): Promise<string | null> {
  try {
    const charWorldbooks = getCharWorldbookNames('current');
    const worldbookNames: string[] = [];

    if (charWorldbooks.primary) {
      worldbookNames.push(charWorldbooks.primary);
    }
    worldbookNames.push(...charWorldbooks.additional);

    const globalNames = getGlobalWorldbookNames();
    worldbookNames.push(...globalNames);

    const uniqueNames = [...new Set(worldbookNames)];

    for (const wbName of uniqueNames) {
      try {
        const entries = await getWorldbook(wbName);
        // 查找语音配置条目（通常是关闭的，不发给 AI）
        const voiceEntry = entries.find(entry => isVoiceConfigEntryName(entry.name));
        if (voiceEntry && voiceEntry.content) {
          return voiceEntry.content;
        }
      } catch (e) {
        continue;
      }
    }

    console.warn('[visual-novel-ui] 未在世界书中找到语音配置条目');
    return null;
  } catch (e) {
    console.error('[visual-novel-ui] 查找语音配置条目时出错:', e);
    return null;
  }
}

/**
 * 从世界书加载资源映射配置
 *
 * @returns 解析后的 ResourceConfig，如果找不到资源条目则返回空配置
 */
export async function loadResourceConfig(): Promise<ResourceConfig> {
  const yamlContent = await findResourceEntry();

  if (!yamlContent) {
    return { characters: {}, backgrounds: {}, bgm: {}, cg: {}, characterAppearances: {} };
  }

  const config = parseResourceYaml(yamlContent);

  // 从 [res]角色外貌 条目加载角色外貌（优先级高于资源库中的角色外貌字段）
  try {
    const { loadCharacterAppearances } = await import('./services/characterAppearances');
    const appearances = await loadCharacterAppearances();
    if (Object.keys(appearances).length > 0) {
      config.characterAppearances = appearances;
    }
  } catch (e) {
    console.warn('[resourceLoader] 加载角色外貌库失败:', e);
  }

  // 从世界书加载语音配置
  try {
    const voiceConfigJson = await findVoiceConfigEntry();
    if (voiceConfigJson) {
      const voiceConfig = JSON.parse(voiceConfigJson);
      if (voiceConfig && typeof voiceConfig === 'object' && !Array.isArray(voiceConfig)) {
        config.voices = voiceConfig;
      } else {
        console.warn('[resourceLoader] 语音配置格式非法，已忽略');
      }
    }
  } catch (e) {
    console.warn('[resourceLoader] 加载语音配置失败:', e);
  }

  return config;
}
