import React from 'react';
import { Fullscreen, Play } from './Icons';

interface LauncherCardProps {
  /** 进入全屏 */
  onEnter: () => void;
  /** 剧情段落数（>0 时显示为小字，可省略） */
  segmentCount?: number;
  /** 标题（默认「视觉小说」） */
  title?: string;
  /** 容器 ref（供父组件量取高度，把楼层 iframe 收到卡片高度） */
  innerRef?: React.Ref<HTMLDivElement>;
}

/**
 * 手机端楼层里的启动卡（原设计）。
 *
 * 楼层 iframe 的宽度被聊天列锁死（手机尤其窄），直接渲染 16:9 游戏画面会让对话框占去大半。
 * 因此手机端只渲染这张卡，点按走酒馆原有的全屏。
 * 卡片保留自身底图（白面板 / 圆角 / 边框 / 阴影），只是外面不再套页面底色、暗角与缩略框。
 */
export const LauncherCard: React.FC<LauncherCardProps> = ({
  onEnter,
  segmentCount = 0,
  title = '视觉小说',
  innerRef,
}) => {
  return (
    <div ref={innerRef} data-nvl-launcher className="relative flex w-full items-center justify-center px-2 py-3 overflow-visible">
      <button
        onClick={onEnter}
        title="进入全屏视觉小说"
        className="group relative z-10 flex w-full max-w-[560px] cursor-pointer items-center gap-4 overflow-hidden rounded-[24px] sm:rounded-[28px] border border-[rgba(0,0,0,0.06)] bg-white/95 px-5 py-4 text-left shadow-[0_2px_8px_rgba(0,0,0,0.06)] hover:shadow-[0_4px_12px_rgba(0,0,0,0.08)] transition-all duration-200 active:scale-[0.99]"
      >
        {/* 徽标 */}
        <span className="relative flex h-12 w-12 shrink-0 items-center justify-center rounded-[22px] bg-[#526070] text-white shadow-sm">
          <Play size={18} className="ml-0.5" />
        </span>

        {/* 文案 */}
        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-2">
            <span className="font-mono-retro text-[8.5px] uppercase tracking-wider text-[#84919e]">
              VISUAL NOVEL UI
            </span>
            <span className="h-px flex-1 bg-[#edf1f4]" />
            {segmentCount > 0 && (
              <span className="font-mono-retro text-[9px] tracking-wider text-[#526070] font-semibold">
                {segmentCount} 段
              </span>
            )}
          </span>
          <span className="mt-1 block truncate font-serif-sc text-[16.5px] font-bold text-[#1e242b]">
            {title}
          </span>
          <span className="mt-0.5 block truncate font-sans-m3 text-[11px] text-[#747f8d]">
            进入无界剧场体验
          </span>
        </span>

        {/* 进入胶囊按钮 */}
        <span className="flex shrink-0 items-center gap-1.5 rounded-full bg-[#526070] hover:bg-[#3d4a58] px-4 py-2 text-[11px] font-sans-m3 font-semibold tracking-wide text-white transition-all">
          <Fullscreen size={13} />
          开启
        </span>
      </button>
    </div>
  );
};
