import React, { useEffect, useRef, useState } from 'react';
import type { CGTaskProgress } from '../types';
import { AlertCircle, CheckCircle2, Loader2, Sparkles } from './Icons';

interface CGProgressBarProps {
  progress: CGTaskProgress;
}

/**
 * CG 生成进度浮层
 * 显示在对话框上方，半透明背景，不遮挡主要内容
 */
export const CGProgressBar: React.FC<CGProgressBarProps> = ({ progress }) => {
  const [visible, setVisible] = useState(false);
  const [fadeOut, setFadeOut] = useState(false);
  const hideTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // 卸载时清掉淡出定时器，避免泄漏
  useEffect(
    () => () => {
      if (hideTimerRef.current) clearTimeout(hideTimerRef.current);
    },
    [],
  );

  useEffect(() => {
    if (progress.status === 'idle') {
      setVisible(false);
      setFadeOut(false);
      return;
    }

    if (progress.status === 'done') {
      // done 状态显示 2 秒后淡出
      setVisible(true);
      setFadeOut(false);
      const timer = setTimeout(() => {
        setFadeOut(true);
        hideTimerRef.current = setTimeout(() => setVisible(false), 300);
      }, 2000);
      return () => clearTimeout(timer);
    }

    // analyzing / generating / error 都显示
    setVisible(true);
    setFadeOut(false);
    return undefined;
  }, [progress.status, progress.completed]);

  if (!visible) return null;

  return (
    <div
      className={`absolute top-2 left-1/2 -translate-x-1/2 z-[50] transition-all duration-300 ${
        fadeOut ? 'opacity-0 translate-y-[-4px]' : 'opacity-100 translate-y-0'
      }`}
    >
      <div className="flex items-center gap-2.5 px-4 py-2 rounded-full bg-white/95 border border-white shadow-[0_4px_16px_rgba(30,36,43,0.08)]">
        {progress.status === 'analyzing' && (
          <>
            <Sparkles size={14} className="text-[#526070] animate-pulse" />
            <span className="text-[11px] font-sans-m3 font-medium text-[#1e242b] tracking-wide">分析场景意境…</span>
          </>
        )}

        {progress.status === 'generating' && (
          <>
            <Loader2 size={14} className="text-[#526070] animate-spin" />
            <span className="text-[11px] font-sans-m3 font-medium text-[#1e242b] tracking-wide">
              生成剧照中 ({progress.completed ?? 0}/{progress.total ?? '?'})
            </span>
            {/* 进度条 */}
            {progress.total && progress.total > 0 && (
              <div className="w-14 h-1.5 rounded-full bg-[#edf1f4] overflow-hidden ml-1">
                <div
                  className="h-full bg-[#526070] rounded-full transition-all duration-300 ease-out"
                  style={{ width: `${((progress.completed ?? 0) / progress.total) * 100}%` }}
                />
              </div>
            )}
          </>
        )}

        {progress.status === 'done' && (
          <>
            <CheckCircle2 size={14} className="text-[#7ca58a]" />
            <span className="text-[11px] font-sans-m3 font-medium text-[#1e242b] tracking-wide">
              生成完成 {progress.completed}/{progress.total}
            </span>
          </>
        )}

        {progress.status === 'error' && (
          <>
            <AlertCircle size={14} className="text-[#c4384c]" />
            <span className="text-[11px] font-sans-m3 text-[#c4384c] tracking-wide max-w-[200px] truncate">
              {progress.error || '生成失败'}
            </span>
          </>
        )}
      </div>
    </div>
  );
};
