import React, { useEffect } from 'react';
import { renderRichText } from '../parser';
import { DialogueSegment } from '../types';
import { CornerDownRight, X } from './Icons';

interface LogScreenProps {
  segments: DialogueSegment[];
  onClose: () => void;
  playSfx: () => void;
  onJumpToSegment?: (index: number) => void;
}

export const LogScreen: React.FC<LogScreenProps> = ({ segments, onClose, playSfx, onJumpToSegment }) => {
  useEffect(() => {
    playSfx();
  }, []);

  const handleClose = () => {
    playSfx();
    onClose();
  };

  return (
    <div className="game-modal fixed inset-0 z-50 flex items-center justify-center p-4 cozy-overlay animate-in fade-in duration-200">
      <div className="relative w-full max-w-3xl h-[88%] rounded-[36px] bg-[#f7f9fa] border border-white shadow-[0_24px_64px_rgba(30,36,43,0.14)] flex flex-col overflow-hidden text-[#1e242b]">
        {/* Header - 类似图3顶部 */}
        <div className="relative z-10 flex justify-between items-center px-8 py-5 border-b border-[#edf1f4] bg-white/70 shrink-0">
          <div className="flex flex-col">
            <h2 className="font-sans-m3 text-[18px] text-[#1e242b] font-bold tracking-tight">
              历史对话流
            </h2>
            <span className="font-mono-retro text-[9px] text-[#84919e] uppercase tracking-wider">
              MESSAGE LOG · {segments.length} ENTRIES
            </span>
          </div>
          <button
            onClick={handleClose}
            className="w-8 h-8 flex items-center justify-center bg-[#edf1f4] hover:bg-[#dde3e8] rounded-full text-[#526070] hover:text-[#1e242b] transition-all cursor-pointer active:scale-95"
          >
            <X size={15} />
          </button>
        </div>

        {/* Content - 极简紧凑历史对话流（类似图5与系统信息流，高度适合长截图与内容回顾） */}
        <div className="flex-1 overflow-y-auto px-4 sm:px-8 py-4 cozy-scrollbar relative z-10">
          {segments.length === 0 && (
            <div className="flex flex-col items-center justify-center h-full text-[#84919e]">
              <span className="font-mono-retro text-sm tracking-widest mb-1">NO RECORDS</span>
              <span className="font-sans-m3 text-xs">暂无对话记录</span>
            </div>
          )}

          <div className="flex flex-col divide-y divide-[#edf1f4] max-w-2xl mx-auto">
            {segments.map((segment, index) => (
              <div
                key={segment.id}
                className="group py-2.5 px-3 rounded-[16px] hover:bg-white/80 transition-all duration-150 flex flex-col gap-1"
              >
                {/* 说话人与楼层号紧凑行 */}
                <div className="flex items-center justify-between text-xs">
                  <div className="flex items-center gap-2">
                    <span className="font-sans-m3 font-bold text-[12.5px] text-[#1e242b]">
                      {segment.speaker}
                    </span>
                    <span className="font-mono-retro text-[8.5px] text-[#84919e]">
                      #{String(index + 1).padStart(3, '0')}
                    </span>
                  </div>

                  {onJumpToSegment && (
                    <button
                      onClick={() => {
                        playSfx();
                        onJumpToSegment(index);
                      }}
                      className="opacity-0 group-hover:opacity-100 flex items-center gap-1 text-[10px] text-[#526070] hover:text-[#1e242b] font-mono-retro transition-opacity cursor-pointer px-1.5 py-0.5 rounded-full hover:bg-[#edf1f4]"
                      title="跳转至此句"
                    >
                      <CornerDownRight size={11} />
                      <span>JUMP</span>
                    </button>
                  )}
                </div>

                {/* 对白正文：紧凑舒适，行高适中 */}
                <p
                  className={`font-serif-sc text-[14px] leading-snug tracking-wide ${segment.isInnerMonologue ? 'italic text-[#747f8d]' : 'text-[#2b333c]'}`}
                  dangerouslySetInnerHTML={{ __html: renderRichText(segment.text || segment.textZh || '') }}
                />
              </div>
            ))}
          </div>
        </div>

        {/* 底部 */}
        <div className="px-8 py-3.5 border-t border-[#edf1f4] bg-white/60 flex justify-between items-center text-[#84919e] font-mono-retro text-[9px]">
          <span>STORY TIMELINE STREAM</span>
          <span>AUTOSCROLL READY</span>
        </div>
      </div>
    </div>
  );
};
